package com.pbtracker;

import org.junit.Test;

import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import java.util.TreeMap;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

public class SyncFingerprintTest
{
	@Test
	public void isIndependentOfMapIterationOrder()
	{
		Map<String, Double> a = new LinkedHashMap<>();
		a.put("zulrah", 42.6);
		a.put("vorkath", 78.0);

		Map<String, Double> b = new LinkedHashMap<>();
		b.put("vorkath", 78.0);
		b.put("zulrah", 42.6);

		assertEquals(
			SyncFingerprint.compute("acct-a", "Zezima", a),
			SyncFingerprint.compute("acct-a", "Zezima", b));
	}

	@Test
	public void producesA64CharacterHexDigest()
	{
		String fingerprint = SyncFingerprint.compute("acct-a", "Zezima", new TreeMap<>());
		assertEquals(64, fingerprint.length());
		assertTrue(fingerprint.matches("[0-9a-f]{64}"));
	}

	@Test
	public void changesWhenAccountHashChanges()
	{
		Map<String, Double> pbs = new TreeMap<>();
		pbs.put("zulrah", 42.6);

		assertNotEquals(
			SyncFingerprint.compute("acct-a", "Zezima", pbs),
			SyncFingerprint.compute("acct-b", "Zezima", pbs));
	}

	@Test
	public void changesWhenDisplayNameChanges()
	{
		Map<String, Double> pbs = new TreeMap<>();
		pbs.put("zulrah", 42.6);

		assertNotEquals(
			SyncFingerprint.compute("acct-a", "Zezima", pbs),
			SyncFingerprint.compute("acct-a", "ZezimaTwo", pbs));
	}

	@Test
	public void normalizesDisplayNameCaseAndWhitespace()
	{
		Map<String, Double> pbs = new TreeMap<>();
		pbs.put("zulrah", 42.6);

		assertEquals(
			SyncFingerprint.compute("acct-a", "Zezima", pbs),
			SyncFingerprint.compute("acct-a", "  ZEZIMA  ", pbs));
	}

	@Test
	public void displayNameNormalizationIsStableUnderTurkishLocale()
	{
		Locale original = Locale.getDefault();
		Map<String, Double> pbs = new TreeMap<>();
		pbs.put("zulrah", 42.6);
		try
		{
			Locale.setDefault(Locale.ENGLISH);
			String english = SyncFingerprint.compute("acct-a", "IRON", pbs);
			Locale.setDefault(new Locale("tr", "TR"));
			assertEquals(english, SyncFingerprint.compute("acct-a", "IRON", pbs));
		}
		finally
		{
			Locale.setDefault(original);
		}
	}

	@Test
	public void changesWhenAPbValueChanges()
	{
		Map<String, Double> a = new TreeMap<>();
		a.put("zulrah", 42.6);

		Map<String, Double> b = new TreeMap<>();
		b.put("zulrah", 42.5);

		assertNotEquals(
			SyncFingerprint.compute("acct-a", "Zezima", a),
			SyncFingerprint.compute("acct-a", "Zezima", b));
	}

	@Test
	public void changesWhenABossKeyIsAddedOrRemoved()
	{
		Map<String, Double> a = new TreeMap<>();
		a.put("zulrah", 42.6);

		Map<String, Double> b = new TreeMap<>();
		b.put("zulrah", 42.6);
		b.put("vorkath", 78.0);

		assertNotEquals(
			SyncFingerprint.compute("acct-a", "Zezima", a),
			SyncFingerprint.compute("acct-a", "Zezima", b));
	}

	@Test
	public void doesNotCollideWhenDelimiterCharacterShiftsBetweenAccountHashAndDisplayName()
	{
		Map<String, Double> pbs = new TreeMap<>();
		pbs.put("zulrah", 42.6);

		assertNotEquals(
			SyncFingerprint.compute("x|y", "z", pbs),
			SyncFingerprint.compute("x", "y|z", pbs));
	}

	@Test
	public void isStableAcrossRepeatedCallsWithTheSameInput()
	{
		Map<String, Double> pbs = new TreeMap<>();
		pbs.put("zulrah", 42.6);

		assertEquals(
			SyncFingerprint.compute("acct-a", "Zezima", pbs),
			SyncFingerprint.compute("acct-a", "Zezima", pbs));
	}
}

package com.pbtracker;

import org.junit.Test;

import java.util.HashMap;
import java.util.Map;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

public class PersistedFingerprintStoreTest
{
	/** In-memory stand-in for RuneLite's ConfigManager, scoped to this plugin's settings group. */
	private static class FakeConfigStore implements PersistedFingerprintStore.ConfigStore
	{
		private final Map<String, String> values = new HashMap<>();

		@Override
		public String get(String key)
		{
			return values.get(key);
		}

		@Override
		public void set(String key, String value)
		{
			values.put(key, value);
		}

		@Override
		public void unset(String key)
		{
			values.remove(key);
		}
	}

	@Test
	public void reportsNoStoredValueForANeverSyncedAccount()
	{
		PersistedFingerprintStore store = new PersistedFingerprintStore(new FakeConfigStore());
		assertFalse(store.matches("acct-a", "fingerprint-1"));
	}

	@Test
	public void reportsAMatchAfterRecordingTheSameFingerprint()
	{
		PersistedFingerprintStore store = new PersistedFingerprintStore(new FakeConfigStore());
		store.record("acct-a", "fingerprint-1");
		assertTrue(store.matches("acct-a", "fingerprint-1"));
	}

	@Test
	public void reportsNoMatchForADifferentFingerprint()
	{
		PersistedFingerprintStore store = new PersistedFingerprintStore(new FakeConfigStore());
		store.record("acct-a", "fingerprint-1");
		assertFalse(store.matches("acct-a", "fingerprint-2"));
	}

	@Test
	public void keepsFingerprintsSeparatePerAccount()
	{
		PersistedFingerprintStore store = new PersistedFingerprintStore(new FakeConfigStore());
		store.record("acct-a", "fingerprint-1");
		assertFalse(store.matches("acct-b", "fingerprint-1"));
	}

	@Test
	public void configKeyUsesAStableOpaqueDigestInsteadOfTheRawAccountHash()
	{
		String accountHash = "raw-account-hash-12345";
		String key = PersistedFingerprintStore.configKeyFor(accountHash);

		assertFalse(key.contains(accountHash));
		assertTrue(key.matches("syncFingerprint\\.v1\\.[0-9a-f]{64}"));
		assertEquals(key, PersistedFingerprintStore.configKeyFor(accountHash));
		assertNotEquals(key, PersistedFingerprintStore.configKeyFor("different-account"));
	}

	@Test
	public void clearRemovesTheStoredValue()
	{
		PersistedFingerprintStore store = new PersistedFingerprintStore(new FakeConfigStore());
		store.record("acct-a", "fingerprint-1");
		store.clear("acct-a");
		assertFalse(store.matches("acct-a", "fingerprint-1"));
	}

	@Test
	public void failsOpenOnAValueWrittenByAFutureSchemaVersion()
	{
		FakeConfigStore raw = new FakeConfigStore();
		// Simulate what a hypothetical future v2 codebase would have
		// written, stashed directly under a raw "v2" key (bypassing
		// today's configKeyFor, which is pinned to v1). A
		// PersistedFingerprintStore built against today's code looks under
		// the v1-prefixed key, won't find this, and must fail open (return
		// false, i.e. sync normally) rather than misreading a differently
		// shaped value - this is the actual cross-version isolation
		// property the versioned key prefix exists to provide.
		raw.set("syncFingerprint.v2.acct-a", "fingerprint-1");
		PersistedFingerprintStore store = new PersistedFingerprintStore(raw);
		assertFalse(store.matches("acct-a", "fingerprint-1"));
	}

	@Test
	public void simulatesAnUnchangedFingerprintSurvivingARestart()
	{
		PersistedFingerprintStore.ConfigStore sharedBackingStore = new FakeConfigStore();

		// First "session"
		PersistedFingerprintStore sessionOne = new PersistedFingerprintStore(sharedBackingStore);
		String fingerprint = "some-64-char-fingerprint-stand-in";
		sessionOne.record("acct-a", fingerprint);

		// Simulated RuneLite restart: a brand new PersistedFingerprintStore
		// instance, but backed by the same persisted config values (this is
		// what real RuneLite does - ConfigManager's storage outlives the
		// plugin object across a restart, only the plugin's own in-memory
		// state, including automaticSyncDeduplicator, is lost).
		PersistedFingerprintStore sessionTwo = new PersistedFingerprintStore(sharedBackingStore);
		assertTrue(sessionTwo.matches("acct-a", fingerprint));
	}
}

package com.pbtracker;

import java.awt.Component;
import java.awt.Container;
import java.awt.event.MouseEvent;
import java.util.Collections;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.swing.JTextArea;
import javax.swing.SwingUtilities;
import org.junit.Test;

import static org.junit.Assert.assertTrue;
import static org.junit.Assert.assertEquals;

public class PbListPanelTest
{
	@Test
	public void escapesSearchTextBeforeRenderingItAsSwingHtml()
	{
		assertEquals("&lt;img src=&quot;x&quot;&gt; &amp; &#39;test&#39;", PbListPanel.escapeHtml("<img src=\"x\"> & 'test'"));
	}

	@Test
	public void clickingVisibleBossTextTriggersNavigation() throws Exception
	{
		AtomicBoolean clicked = new AtomicBoolean();
		SwingUtilities.invokeAndWait(() ->
		{
			PbListPanel panel = new PbListPanel(null, null);
			SyncClient.PlayerLookupResponse player = new SyncClient.PlayerLookupResponse();
			player.displayName = "Tester";
			SyncClient.PbEntryDto pb = new SyncClient.PbEntryDto();
			pb.boss = "zulrah";
			pb.timeSeconds = 60;
			pb.rank = 1;
			player.pbs = Collections.singletonList(pb);
			panel.showPlayer(player, (boss, name) -> clicked.set(true));

			JTextArea heading = findTextArea(panel, "Zulrah");
			heading.dispatchEvent(new MouseEvent(heading, MouseEvent.MOUSE_PRESSED,
				System.currentTimeMillis(), 0, 2, 2, 1, false));
		});
		assertTrue(clicked.get());
	}

	@Test
	public void lateBossListRerendersAnAlreadyLoadedPlayer() throws Exception
	{
		SwingUtilities.invokeAndWait(() ->
		{
			PbListPanel panel = new PbListPanel(null, null);
			SyncClient.PlayerLookupResponse player = new SyncClient.PlayerLookupResponse();
			player.displayName = "Tester";
			SyncClient.PbEntryDto pb = new SyncClient.PbEntryDto();
			pb.boss = "zulrah";
			pb.timeSeconds = 60;
			pb.rank = 1;
			player.pbs = Collections.singletonList(pb);

			panel.showPlayer(player, (boss, name) -> { });
			panel.setAllBosses(java.util.List.of("zulrah", "vorkath"));

			assertTrue(findTextAreaOrNull(panel, "Vorkath") != null);
		});
	}

	private static final class FakeConfig implements PbTrackerConfig
	{
		private final boolean showOverall;
		private final boolean showRoom;

		FakeConfig(boolean showOverall, boolean showRoom)
		{
			this.showOverall = showOverall;
			this.showRoom = showRoom;
		}

		@Override
		public boolean showOverallVariants()
		{
			return showOverall;
		}

		@Override
		public boolean showRoomVariants()
		{
			return showRoom;
		}
	}

	@Test
	public void hidesOverallVariantRowsWhenConfiguredOff() throws Exception
	{
		SwingUtilities.invokeAndWait(() ->
		{
			PbListPanel panel = new PbListPanel(null, new FakeConfig(false, true));
			SyncClient.PlayerLookupResponse player = new SyncClient.PlayerLookupResponse();
			player.displayName = "Tester";
			SyncClient.PbEntryDto overall = new SyncClient.PbEntryDto();
			overall.boss = "theatre of blood - fastest overall (3 player)";
			overall.timeSeconds = 1200;
			overall.rank = 2;
			SyncClient.PbEntryDto room = new SyncClient.PbEntryDto();
			room.boss = "theatre of blood - fastest room (3 player)";
			room.timeSeconds = 500;
			room.rank = 1;
			player.pbs = java.util.List.of(overall, room);
			panel.showPlayer(player, (boss, name) -> { });

			JTextArea heading = findTextArea(panel, "Theatre Of Blood");
			heading.dispatchEvent(new MouseEvent(heading, MouseEvent.MOUSE_PRESSED,
				System.currentTimeMillis(), 0, 2, 2, 1, false));

			assertTrue(findTextAreaOrNull(panel, "Trio - Room   8:20   #1") != null);
			assertTrue(findTextAreaOrNull(panel, "Trio - Overall   20:00   #2") == null);
		});
	}

	private static JTextArea findTextArea(Container root, String text)
	{
		for (Component child : root.getComponents())
		{
			if (child instanceof JTextArea && ((JTextArea) child).getText().equals(text))
			{
				return (JTextArea) child;
			}
			if (child instanceof Container)
			{
				JTextArea found = findTextAreaOrNull((Container) child, text);
				if (found != null)
				{
					return found;
				}
			}
		}
		throw new AssertionError("Text area not found: " + text);
	}

	private static JTextArea findTextAreaOrNull(Container root, String text)
	{
		for (Component child : root.getComponents())
		{
			if (child instanceof JTextArea && ((JTextArea) child).getText().equals(text))
			{
				return (JTextArea) child;
			}
			if (child instanceof Container)
			{
				JTextArea found = findTextAreaOrNull((Container) child, text);
				if (found != null)
				{
					return found;
				}
			}
		}
		return null;
	}
}

package com.pbtracker;

