	private static SyncClient.PbEntryDto pb(String boss, double timeSeconds, int rank)
	{
		SyncClient.PbEntryDto dto = new SyncClient.PbEntryDto();
		dto.boss = boss;
		dto.timeSeconds = timeSeconds;
		dto.rank = rank;
		return dto;
