		InstallRecoveryCircuitBreaker breaker = new InstallRecoveryCircuitBreaker();
		String fingerprint = SyncFingerprint.compute(ACCOUNT, NAME, pbs());

		coordinator.complete(true, ACCOUNT, ACCOUNT, fingerprint, changedOutcome());
		assertTrue(coordinator.shouldSkip(false, ACCOUNT, fingerprint));

		SyncClient.SyncErrorResponse pending = SyncClient.parseSyncErrorBody(
			new com.google.gson.Gson(),
			"{\"code\":\"RECOVERY_PENDING\",\"recoveryId\":7,\"retryAfterSeconds\":60}");
		coordinator.invalidateFingerprint(ACCOUNT);
		breaker.recordMismatch(ACCOUNT, pending, 1_000L);

		assertFalse(breaker.beginAutomaticAttempt(ACCOUNT, 60_999L).allowed);
		assertTrue(breaker.beginAutomaticAttempt(ACCOUNT, 61_000L).allowed);
		assertFalse(coordinator.shouldSkip(false, ACCOUNT, fingerprint));
	}

	@Test
	public void persistedSkipCannotLeaveARecoveryProbePermanentlyInFlight()
	{
		FakeConfigStore persistedConfig = new FakeConfigStore();
		PersistentSyncCoordinator coordinator = new PersistentSyncCoordinator(
			new PersistedFingerprintStore(persistedConfig), new LocalProfileLoadCoordinator());
		InstallRecoveryCircuitBreaker breaker = new InstallRecoveryCircuitBreaker();
		String fingerprint = SyncFingerprint.compute(ACCOUNT, NAME, pbs());
		coordinator.complete(true, ACCOUNT, ACCOUNT, fingerprint, changedOutcome());

		SyncClient.SyncErrorResponse pending = SyncClient.parseSyncErrorBody(
			new com.google.gson.Gson(),
			"{\"code\":\"RECOVERY_PENDING\",\"retryAfterSeconds\":60}");
		breaker.recordMismatch(ACCOUNT, pending, 1_000L);
		assertTrue(breaker.beginAutomaticAttempt(ACCOUNT, 61_000L).allowed);
		assertTrue(coordinator.shouldSkip(false, ACCOUNT, fingerprint));

		// Mirrors the persisted-skip branch in PbTrackerPlugin.
		breaker.completeUnsuccessfulAutomaticAttempt(ACCOUNT, 61_000L);
		assertFalse(breaker.beginAutomaticAttempt(ACCOUNT, 120_999L).allowed);
		assertTrue(breaker.beginAutomaticAttempt(ACCOUNT, 121_000L).allowed);
	}
}

package com.pbtracker;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class InstallRecoveryRetryCoordinatorTest
{
	@Test
	public void dueTimerInvokesExactlyOneRetryAndPersistsOnlyDeadline()
	{
		Harness harness = new Harness();
		harness.coordinator.schedule("account-a", 900_000L);

		assertEquals(Long.valueOf(901_000L), harness.store.get("account-a"));
		assertEquals(1, harness.timer.tasks.size());
		assertEquals(900_000L, harness.timer.tasks.get(0).delayMillis);

		harness.timer.tasks.get(0).runEvenIfCancelled();
		assertEquals(1, harness.retriedAccounts.size());
		assertEquals("account-a", harness.retriedAccounts.get(0));

		// Re-running a ScheduledFuture's callback cannot duplicate the probe.
		harness.timer.tasks.get(0).runEvenIfCancelled();
		assertEquals(1, harness.retriedAccounts.size());
	}

	@Test
	public void rescheduleKeepsOneLiveTimerAndStaleCallbackCannotFire()
	{
		Harness harness = new Harness();
		harness.coordinator.schedule("account-a", 900_000L);
		FakeTask oldTask = harness.timer.tasks.get(0);
		harness.coordinator.schedule("account-a", 60_000L);

		assertTrue(oldTask.cancelled);
		assertEquals(2, harness.timer.tasks.size());
		oldTask.runEvenIfCancelled();
		assertTrue(harness.retriedAccounts.isEmpty());

		harness.timer.tasks.get(1).runEvenIfCancelled();
		assertEquals(java.util.Collections.singletonList("account-a"), harness.retriedAccounts);
	}

	@Test
	public void accountSwitchLogoutAndShutdownCancellationPreserveDurableRetry()
	{
		Harness harness = new Harness();
		harness.coordinator.schedule("account-a", 900_000L);
		FakeTask accountATask = harness.timer.tasks.get(0);

		harness.coordinator.activateAccount("account-b");
		assertTrue(accountATask.cancelled);
		assertEquals(Long.valueOf(901_000L), harness.store.get("account-a"));
		accountATask.runEvenIfCancelled();
		assertTrue(harness.retriedAccounts.isEmpty());

		// Returning to the account restores the same deadline even when the
		// ordinary sync-on-login preference is disabled by the caller.
		harness.clock.now = 101_000L;
		harness.coordinator.activateAccount("account-a");
		FakeTask restored = harness.timer.tasks.get(1);
		assertEquals(800_000L, restored.delayMillis);

		harness.coordinator.cancelTimer(); // logout/shutdown
		assertTrue(restored.cancelled);
		assertEquals(Long.valueOf(901_000L), harness.store.get("account-a"));
		restored.runEvenIfCancelled();
		assertTrue(harness.retriedAccounts.isEmpty());
	}

	@Test
	public void successClearsDeadlineAndCancelsPendingTimer()
	{
		Harness harness = new Harness();
		harness.coordinator.schedule("account-a", 60_000L);
		FakeTask pending = harness.timer.tasks.get(0);

		harness.coordinator.clear("account-a");
		assertTrue(pending.cancelled);
		assertNull(harness.store.get("account-a"));
		pending.runEvenIfCancelled();
		assertTrue(harness.retriedAccounts.isEmpty());
	}

	@Test
	public void ensureScheduledDoesNotPushAValidDeadlineForward()
	{
		Harness harness = new Harness();
		harness.coordinator.schedule("account-a", 900_000L);
		FakeTask original = harness.timer.tasks.get(0);

		harness.clock.now = 2_000L;
		harness.coordinator.ensureScheduled("account-a", 900_000L);
		assertFalse(original.cancelled);
		assertEquals(1, harness.timer.tasks.size());
		assertEquals(Long.valueOf(901_000L), harness.store.get("account-a"));
	}

	@Test
	public void overduePersistedDeadlineRestoresAsImmediateAutomaticProbe()
	{
		Harness harness = new Harness();
		harness.store.set("account-a", 500L);
		harness.clock.now = 1_000L;

		harness.coordinator.restore("account-a");
		assertEquals(0L, harness.timer.tasks.get(0).delayMillis);
		harness.timer.tasks.get(0).runEvenIfCancelled();
		assertEquals(java.util.Collections.singletonList("account-a"), harness.retriedAccounts);
	}

	@Test
	public void failedRestoredProbeRearmsOneBoundedTimerButOrdinaryFailureDoesNot()
	{
		FakeClock clock = new FakeClock();
		clock.now = 1_000L;
		FakeTimer timer = new FakeTimer();
		FakeStore store = new FakeStore();
		store.set("recovery-account", 500L);
		InstallRecoveryRetryCoordinator[] holder = new InstallRecoveryRetryCoordinator[1];
		holder[0] = new InstallRecoveryRetryCoordinator(
			clock,
			timer,
			store,
			account -> holder[0].scheduleFallbackIfTracked(account, 300_000L),
			(account, delay) -> delay);

		holder[0].activateAccount("recovery-account");
		assertEquals(0L, timer.tasks.get(0).delayMillis);
		timer.tasks.get(0).runEvenIfCancelled(); // reconstructed probe fails/returns 5xx

		assertEquals(2, timer.tasks.size());
		assertEquals(300_000L, timer.tasks.get(1).delayMillis);
		assertEquals(Long.valueOf(301_000L), store.get("recovery-account"));
		assertFalse(timer.tasks.get(1).cancelled);

		assertFalse(holder[0].scheduleFallbackIfTracked("ordinary-account", 300_000L));
		assertEquals("ordinary failure must not create a recovery timer", 2, timer.tasks.size());
		assertNull(store.get("ordinary-account"));
	}

	@Test
	public void lateInactiveAccountResponseCannotReplaceActiveTimerAndRestoresOnReturn()
	{
		Harness harness = new Harness();
		harness.coordinator.schedule("account-a", 900_000L);

		harness.coordinator.activateAccount("account-b");
		harness.coordinator.schedule("account-b", 60_000L);
		FakeTask accountBTimer = harness.timer.tasks.get(1);
		Long accountBDeadline = harness.store.get("account-b");
		String visibleStatus = "B recovery remains active";

		// A's late 409/network/5xx callback persists A's new retry state but
		// must not cancel or replace B's sole live timer.
		harness.coordinator.schedule("account-a", 300_000L);
		if (PbTrackerPlugin.shouldApplyAccountScopedUpdate(
			"account-a", "account-b", "account-b", true))
		{
			visibleStatus = "late A response";
		}
		assertFalse(accountBTimer.cancelled);
		assertEquals(2, harness.timer.tasks.size());
		assertEquals(accountBDeadline, harness.store.get("account-b"));
		assertEquals(Long.valueOf(301_000L), harness.store.get("account-a"));
		assertEquals("B recovery remains active", visibleStatus);

		harness.coordinator.activateAccount("account-a");
		assertTrue(accountBTimer.cancelled);
		assertEquals(3, harness.timer.tasks.size());
		assertEquals(300_000L, harness.timer.tasks.get(2).delayMillis);
	}

	@Test
	public void deterministicJitterIsStablePositiveAndBounded()
	{
		long base = 900_000L;
		long first = InstallRecoveryRetryCoordinator.boundedDeterministicJitter("account-a", base);
		long second = InstallRecoveryRetryCoordinator.boundedDeterministicJitter("account-a", base);

		assertEquals(first, second);
		assertTrue(first >= base);
		assertTrue(first <= base + 90_000L);
		assertEquals(0L, InstallRecoveryRetryCoordinator.boundedDeterministicJitter("account-a", 0L));
	}

	private static final class Harness
	{
		final FakeClock clock = new FakeClock();
		final FakeTimer timer = new FakeTimer();
		final FakeStore store = new FakeStore();
		final List<String> retriedAccounts = new ArrayList<>();
		final InstallRecoveryRetryCoordinator coordinator = new InstallRecoveryRetryCoordinator(
			clock, timer, store, retriedAccounts::add, (account, delay) -> delay);

		Harness()
		{
			clock.now = 1_000L;
			coordinator.activateAccount("account-a");
		}
	}

	private static final class FakeClock implements InstallRecoveryRetryCoordinator.Clock
	{
		long now;

		@Override
		public long nowMillis()
		{
			return now;
		}
	}

	private static final class FakeTimer implements InstallRecoveryRetryCoordinator.Timer
	{
		final List<FakeTask> tasks = new ArrayList<>();

		@Override
		public InstallRecoveryRetryCoordinator.Cancellable schedule(Runnable task, long delayMillis)
		{
			FakeTask scheduled = new FakeTask(task, delayMillis);
			tasks.add(scheduled);
			return scheduled;
		}
	}

	private static final class FakeTask implements InstallRecoveryRetryCoordinator.Cancellable
	{
		final Runnable runnable;
		final long delayMillis;
		boolean cancelled;

		FakeTask(Runnable runnable, long delayMillis)
		{
			this.runnable = runnable;
			this.delayMillis = delayMillis;
		}

		@Override
		public void cancel()
		{
			cancelled = true;
		}

		void runEvenIfCancelled()
		{
			runnable.run();
		}
	}

	private static final class FakeStore implements InstallRecoveryRetryCoordinator.DeadlineStore
	{
		final Map<String, Long> values = new HashMap<>();

		@Override
		public Long get(String accountHash)
		{
			return values.get(accountHash);
		}

		@Override
		public void set(String accountHash, long deadlineMillis)
		{
			values.put(accountHash, deadlineMillis);
		}

		@Override
		public void clear(String accountHash)
		{
			values.remove(accountHash);
		}
	}
}

package com.pbtracker;

import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;

public class PersistedRecoveryRetryStoreTest
{
	@Test
	public void storesOnlyDeadlineUnderOpaqueAccountSpecificKey()
	{
		FakeConfigStore config = new FakeConfigStore();
		PersistedRecoveryRetryStore store = new PersistedRecoveryRetryStore(config);

		store.set("123456789", 900_000L);
		String key = PersistedRecoveryRetryStore.configKeyFor("123456789");

		assertFalse(key.contains("123456789"));
		assertEquals("900000", config.values.get(key));
		assertEquals(Long.valueOf(900_000L), store.get("123456789"));
		assertNull(store.get("different-account"));
	}

	@Test
	public void malformedDeadlineFailsOpenAndSuccessCanClearIt()
	{
		FakeConfigStore config = new FakeConfigStore();
		PersistedRecoveryRetryStore store = new PersistedRecoveryRetryStore(config);
		String key = PersistedRecoveryRetryStore.configKeyFor("account-a");
		config.values.put(key, "RECOVERY_PENDING:42:secret");

		assertNull(store.get("account-a"));
		store.clear("account-a");
		assertFalse(config.values.containsKey(key));
	}

	private static final class FakeConfigStore implements PersistedFingerprintStore.ConfigStore
	{
		final Map<String, String> values = new HashMap<>();

		@Override
		public String get(String key)
		{
			return values.get(key);
		}

		@Override
		public void set(String key, String value)
		{
			values.put(key, value);
		}

		@Override
		public void unset(String key)
		{
			values.remove(key);
		}
	}
}

package com.pbtracker;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class LocalProfileLoadCoordinatorTest
{
	@Test
	public void firstLoginStateForAnAccountSchedulesOneLoad()
	{
		LocalProfileLoadCoordinator coordinator = new LocalProfileLoadCoordinator();
		assertEquals(
			LocalProfileLoadCoordinator.Decision.LOAD,
			coordinator.onLoginState("acct-a", "Zezima", 1_000L));
	}

	@Test
	public void repeatedLoginStatesForTheSameAccountAndNameDoNotScheduleAnotherLookup()
	{
		LocalProfileLoadCoordinator coordinator = new LocalProfileLoadCoordinator();
		coordinator.onLoginState("acct-a", "Zezima", 1_000L);
		coordinator.markLoaded();

		assertEquals(
			LocalProfileLoadCoordinator.Decision.SKIP_ALREADY_LOADED,
			coordinator.onLoginState("acct-a", "Zezima", 2_000L));
	}

	@Test
	public void worldHopSchedulesNoAdditionalLookupOnceLoaded()
	{
		LocalProfileLoadCoordinator coordinator = new LocalProfileLoadCoordinator();
		coordinator.onLoginState("acct-a", "Zezima", 1_000L);
		coordinator.markLoaded();

		// A world hop just republishes LOGGED_IN for the same account/name.
		assertEquals(
			LocalProfileLoadCoordinator.Decision.SKIP_ALREADY_LOADED,
			coordinator.onLoginState("acct-a", "Zezima", 5_000L));
	}

	@Test
	public void accountSwitchSchedulesOneLookupForTheNewAccount()
	{
		LocalProfileLoadCoordinator coordinator = new LocalProfileLoadCoordinator();
		coordinator.onLoginState("acct-a", "Zezima", 1_000L);
		coordinator.markLoaded();

		assertEquals(
			LocalProfileLoadCoordinator.Decision.LOAD,
			coordinator.onLoginState("acct-b", "AltAccount", 2_000L));
	}

	@Test
	public void normalizedSameNameCoalescesAnInFlightLookup()
	{
		LocalProfileLoadCoordinator coordinator = new LocalProfileLoadCoordinator();
		coordinator.onLoginState("acct-a", "Zezima", 1_000L); // now in flight

		assertEquals(
			LocalProfileLoadCoordinator.Decision.SKIP_IN_FLIGHT,
			coordinator.onLoginState("acct-a", "  ZEZIMA  ", 1_001L));
	}

	@Test
	public void nameChangePermitsOneNewLookup()
	{
		LocalProfileLoadCoordinator coordinator = new LocalProfileLoadCoordinator();
		coordinator.onLoginState("acct-a", "Zezima", 1_000L);
		coordinator.markLoaded();

		assertEquals(
			LocalProfileLoadCoordinator.Decision.LOAD,
			coordinator.onLoginState("acct-a", "ZezimaTwo", 2_000L));
	}

	@Test
	public void errorBackoffPreventsRapidRetries()
	{
		LocalProfileLoadCoordinator coordinator = new LocalProfileLoadCoordinator();
		coordinator.onLoginState("acct-a", "Zezima", 1_000L);
		coordinator.markError(1_000L);

		assertEquals(
			LocalProfileLoadCoordinator.Decision.SKIP_BACKOFF,
			coordinator.onLoginState("acct-a", "Zezima", 1_500L));
		assertEquals(
			LocalProfileLoadCoordinator.Decision.LOAD,
			coordinator.onLoginState("acct-a", "Zezima", 31_001L));
	}

	@Test
	public void manualRefreshBypassesLoadedStateButCoalescesConcurrentRefreshes()
	{
		LocalProfileLoadCoordinator coordinator = new LocalProfileLoadCoordinator();
		coordinator.onLoginState("acct-a", "Zezima", 1_000L);
		coordinator.markLoaded();

		assertEquals(
			LocalProfileLoadCoordinator.Decision.LOAD,
			coordinator.onManualRefresh("acct-a", "Zezima"));
		assertEquals(
			LocalProfileLoadCoordinator.Decision.SKIP_IN_FLIGHT,
			coordinator.onManualRefresh("acct-a", "Zezima"));
	}

	@Test
	public void manualRefreshForADifferentSessionDoesNotLeakStaleLoadedOrBackoffState()
	{
		LocalProfileLoadCoordinator coordinator = new LocalProfileLoadCoordinator();
		coordinator.onLoginState("acct-a", "Zezima", 1_000L);
		coordinator.markLoaded();
		coordinator.markError(1_000L); // simulate a stale backoff timestamp left on the old session

		// Manual refresh for a different account should not be blocked by the
		// old session's loaded/backoff state, and should not carry that state
		// forward into the new session either.
		assertEquals(
			LocalProfileLoadCoordinator.Decision.LOAD,
			coordinator.onManualRefresh("acct-b", "AltAccount"));

		// The new session should behave like a freshly tracked one: a
		// concurrent manual refresh for it coalesces...
		assertEquals(
			LocalProfileLoadCoordinator.Decision.SKIP_IN_FLIGHT,
			coordinator.onManualRefresh("acct-b", "AltAccount"));

		// ...and once it completes, no stale loaded=true or backoff timestamp
		// from acct-a should cause onLoginState to skip a subsequent load.
		coordinator.markError(1_500L);
		assertEquals(
			LocalProfileLoadCoordinator.Decision.LOAD,
			coordinator.onLoginState("acct-b", "AltAccount", 100_000L));
	}

	@Test
	public void logoutClearsTheSessionAndPermitsANewLoadOnNextLogin()
	{
		LocalProfileLoadCoordinator coordinator = new LocalProfileLoadCoordinator();
		coordinator.onLoginState("acct-a", "Zezima", 1_000L);
		coordinator.markLoaded();

		coordinator.reset();

		assertEquals(
			LocalProfileLoadCoordinator.Decision.LOAD,
			coordinator.onLoginState("acct-a", "Zezima", 2_000L));
	}

	@Test
	public void successfulSyncWithChangedDataAllowsOneRefresh()
	{
		LocalProfileLoadCoordinator coordinator = new LocalProfileLoadCoordinator();
		coordinator.onLoginState("acct-a", "Zezima", 1_000L);
		coordinator.markLoaded();

		coordinator.markStaleAfterChangedSync();

		assertEquals(
			LocalProfileLoadCoordinator.Decision.LOAD,
			coordinator.onLoginState("acct-a", "Zezima", 2_000L));
	}

	@Test
	public void unchangedOrReplayedSyncDoesNotForceARefresh()
	{
		LocalProfileLoadCoordinator coordinator = new LocalProfileLoadCoordinator();
		coordinator.onLoginState("acct-a", "Zezima", 1_000L);
		coordinator.markLoaded(false);

		assertFalse(coordinator.requestRefreshAfterSuccessfulSync(false));
		assertEquals(
			LocalProfileLoadCoordinator.Decision.SKIP_ALREADY_LOADED,
			coordinator.onLoginState("acct-a", "Zezima", 2_000L));
	}

	@Test
	public void unchangedSyncRefreshesAPriorNotFoundResultOnce()
	{
		LocalProfileLoadCoordinator coordinator = new LocalProfileLoadCoordinator();
		coordinator.onLoginState("acct-a", "RenamedPlayer", 1_000L);
		coordinator.markLoaded(true);

		assertTrue(coordinator.requestRefreshAfterSuccessfulSync(false));
		assertEquals(
			LocalProfileLoadCoordinator.Decision.LOAD,
			coordinator.onLoginState("acct-a", "RenamedPlayer", 2_000L));
	}

	@Test
	public void unchangedSyncDuringAValidLoadDoesNotCreateASecondLookup()
	{
		LocalProfileLoadCoordinator coordinator = new LocalProfileLoadCoordinator();
		coordinator.onLoginState("acct-a", "Zezima", 1_000L);

		assertFalse(coordinator.requestRefreshAfterSuccessfulSync(false));
		assertFalse(coordinator.markLoaded(false));
		assertEquals(
			LocalProfileLoadCoordinator.Decision.SKIP_ALREADY_LOADED,
			coordinator.onLoginState("acct-a", "Zezima", 2_000L));
	}

	@Test
	public void unchangedSyncDuringANotFoundLoadRetriesAfterTheOutcomeIsKnown()
	{
		LocalProfileLoadCoordinator coordinator = new LocalProfileLoadCoordinator();
		coordinator.onLoginState("acct-a", "RenamedPlayer", 1_000L);

		assertFalse(coordinator.requestRefreshAfterSuccessfulSync(false));
		assertTrue(coordinator.markLoaded(true));
		assertEquals(
			LocalProfileLoadCoordinator.Decision.SKIP_IN_FLIGHT,
			coordinator.onLoginState("acct-a", "RenamedPlayer", 2_000L));

		assertFalse(coordinator.markLoaded(false));
	}

	@Test
	public void changedSyncArrivingMidLoadIsNotSwallowedByThatLoadCompleting()
	{
		LocalProfileLoadCoordinator coordinator = new LocalProfileLoadCoordinator();
		// An unrelated lookup is already in flight (e.g. a world hop retry)...
		coordinator.onLoginState("acct-a", "Zezima", 1_000L);

		// ...and a changed-data sync's onResponse fires while it's still in flight.
		coordinator.markStaleAfterChangedSync();

		// The unrelated in-flight lookup now completes. Without pendingRefresh,
		// this would set loaded=true and permanently mask the missed refresh.
		// A refresh is still owed, so markLoaded() reports true and inFlight
		// stays held - the caller (MyPbsTab) is required to immediately
		// retry with a new load rather than the coordinator relying on some
		// later onLoginState to notice. A login state re-check right now
		// must therefore see SKIP_IN_FLIGHT, not LOAD - the retry itself is
		// the mechanism that isn't swallowed, not a fresh onLoginState LOAD.
		assertTrue(coordinator.markLoaded());
		assertEquals(
			LocalProfileLoadCoordinator.Decision.SKIP_IN_FLIGHT,
			coordinator.onLoginState("acct-a", "Zezima", 2_000L));

		// The retry itself now completes with nothing further pending -
		// proof the changed sync's refresh was genuinely serviced, not
		// dropped, is that the session settles into loaded=true here.
		assertFalse(coordinator.markLoaded());
		assertEquals(
			LocalProfileLoadCoordinator.Decision.SKIP_ALREADY_LOADED,
			coordinator.onLoginState("acct-a", "Zezima", 3_000L));
	}

	@Test
	public void markLoadedReturnsFalseInTheNormalNoPendingRefreshCase()
	{
		LocalProfileLoadCoordinator coordinator = new LocalProfileLoadCoordinator();
		coordinator.onLoginState("acct-a", "Zezima", 1_000L);

		assertFalse(coordinator.markLoaded());
	}

	@Test
	public void markLoadedReturnsTrueWhenARefreshWasPendingAndConsumesIt()
	{
		LocalProfileLoadCoordinator coordinator = new LocalProfileLoadCoordinator();
		// An unrelated lookup is already in flight (e.g. a world hop retry)...
		coordinator.onLoginState("acct-a", "Zezima", 1_000L);
		// ...and a changed-data sync's onResponse fires while it's still in flight.
		coordinator.markStaleAfterChangedSync();

		// The in-flight lookup completes: a refresh is still owed, so this must
		// report true so the caller knows to immediately start another load
		// rather than treating the session as up to date.
		assertTrue(coordinator.markLoaded());

		// That pendingRefresh was consumed, so the caller's own re-triggered
		// load's eventual markLoaded() call sees nothing pending and reports false.
		assertFalse(coordinator.markLoaded());
	}

	@Test
	public void markLoadedClearsStaleFailureBackoffTimestamp()
	{
		LocalProfileLoadCoordinator coordinator = new LocalProfileLoadCoordinator();
		coordinator.onLoginState("acct-a", "Zezima", 1_000L);
		coordinator.markError(1_000L); // sets lastFailureAtMillis = 1_000L

		// A later load for the same session (past the 30s backoff window)
		// succeeds...
		coordinator.onLoginState("acct-a", "Zezima", 31_001L);
		coordinator.markLoaded();

		// Force loaded back to false (as markStaleAfterChangedSync() would)
		// so onLoginState re-evaluates the backoff check instead of short
		// circuiting on SKIP_ALREADY_LOADED - this isolates whether the old
		// (now stale) failure timestamp from 1_000L was actually cleared by
		// the successful markLoaded() above.
		coordinator.markStaleAfterChangedSync();

		assertEquals(
			LocalProfileLoadCoordinator.Decision.LOAD,
			coordinator.onLoginState("acct-a", "Zezima", 31_100L));
	}

	@Test
	public void aSecondChangedSyncArrivingDuringTheRetryWindowIsStillDeferredNotDropped()
	{
		LocalProfileLoadCoordinator coordinator = new LocalProfileLoadCoordinator();

		// Load A starts (inFlight = true).
		assertEquals(
			LocalProfileLoadCoordinator.Decision.LOAD,
			coordinator.onLoginState("acct-a", "Zezima", 1_000L));

		// Changed sync #1 lands while A is in flight - deferred via pendingRefresh.
		coordinator.markStaleAfterChangedSync();

		// Load A completes: a refresh is still owed, so the caller retries
		// immediately with load B. inFlight must stay true across that
		// hand-off, since B is a real in-progress fetch from the
		// coordinator's point of view, not a fresh, idle session.
		assertTrue(coordinator.markLoaded());

		// Proof inFlight is still held: a login state re-check right now
		// (as would happen from an unrelated world hop firing mid-retry)
		// must see SKIP_IN_FLIGHT, not LOAD - if inFlight had been wrongly
		// cleared already, this would incorrectly return LOAD and schedule
		// a second, redundant lookup on top of retry B.
		assertEquals(
			LocalProfileLoadCoordinator.Decision.SKIP_IN_FLIGHT,
			coordinator.onLoginState("acct-a", "Zezima", 1_100L));

		// Changed sync #2 lands while retry B is in flight. Since inFlight
		// is (correctly) still true, this must take the pendingRefresh
		// branch again rather than clearing loaded directly.
		coordinator.markStaleAfterChangedSync();

		// Load B completes: proof sync #2 wasn't silently dropped is that
		// markLoaded() reports a refresh is owed a second time, triggering
		// yet another retry rather than settling into loaded=true.
		assertTrue(coordinator.markLoaded());

		// Finally, retry C (for sync #2) completes with nothing further
		// pending, and the session settles into a genuinely loaded state.
		assertFalse(coordinator.markLoaded());
	}

	@Test
	public void changedSyncRefreshSurvivesAnInFlightLookupError()
	{
		LocalProfileLoadCoordinator coordinator = new LocalProfileLoadCoordinator();
		coordinator.onLoginState("acct-a", "Zezima", 1_000L);
		assertTrue(coordinator.requestRefreshAfterSuccessfulSync(true));

		assertTrue(coordinator.markError(1_100L));
		assertEquals(
			LocalProfileLoadCoordinator.Decision.SKIP_IN_FLIGHT,
			coordinator.onLoginState("acct-a", "Zezima", 1_101L));

		assertFalse(coordinator.markLoaded(false));
	}

	@Test
	public void successfulSyncRetriesAPriorLookupErrorWithoutWaitingForAnotherLoginEvent()
	{
		LocalProfileLoadCoordinator coordinator = new LocalProfileLoadCoordinator();
		coordinator.onLoginState("acct-a", "Zezima", 1_000L);
		assertFalse(coordinator.markError(1_100L));

		assertTrue(coordinator.requestRefreshAfterSuccessfulSync(false));
		assertEquals(
			LocalProfileLoadCoordinator.Decision.LOAD,
			coordinator.onLoginState("acct-a", "Zezima", 1_101L));
	}
}

