package com.pbtracker;

/**
 * Owns the single passive install-recovery timer. The persisted value is only
 * an opaque account's next-attempt timestamp; recovery IDs, response codes,
 * credentials, and PB payloads are never retained here.
 */
final class InstallRecoveryRetryCoordinator
{
	interface Clock
	{
		long nowMillis();
	}

	interface Timer
	{
		Cancellable schedule(Runnable task, long delayMillis);
	}

	interface Cancellable
	{
		void cancel();
	}

	interface DeadlineStore
	{
		Long get(String accountHash);

		void set(String accountHash, long deadlineMillis);

		void clear(String accountHash);
	}

	interface RetryAction
	{
		void retry(String accountHash);
	}

	interface Jitter
	{
		long addToDelay(String accountHash, long delayMillis);
	}

	private final Clock clock;
	private final Timer timer;
	private final DeadlineStore store;
	private final RetryAction retryAction;
	private final Jitter jitter;
	private long generation;
	private Cancellable pending;
	private String pendingAccountHash;
	private String activeAccountHash;

	InstallRecoveryRetryCoordinator(
		Clock clock,
		Timer timer,
		DeadlineStore store,
		RetryAction retryAction,
		Jitter jitter)
	{
		this.clock = clock;
		this.timer = timer;
		this.store = store;
		this.retryAction = retryAction;
		this.jitter = jitter;
	}

	synchronized void schedule(String accountHash, long baseDelayMillis)
	{
		long delayMillis = Math.max(0L, jitter.addToDelay(accountHash, Math.max(0L, baseDelayMillis)));
		long deadlineMillis = saturatingAdd(clock.nowMillis(), delayMillis);
		store.set(accountHash, deadlineMillis);
		if (accountHash.equals(activeAccountHash))
		{
			arm(accountHash, delayMillis);
		}
	}

	synchronized void ensureScheduled(String accountHash, long baseDelayMillis)
	{
		Long existingDeadline = store.get(accountHash);
		if (existingDeadline != null && existingDeadline > clock.nowMillis())
		{
			if (accountHash.equals(activeAccountHash) && !accountHash.equals(pendingAccountHash))
			{
				arm(accountHash, existingDeadline - clock.nowMillis());
			}
			return;
		}
		schedule(accountHash, baseDelayMillis);
	}

	synchronized void restore(String accountHash)
	{
		if (!accountHash.equals(activeAccountHash))
		{
			return;
		}
		Long deadlineMillis = store.get(accountHash);
		if (deadlineMillis == null)
		{
			return;
		}
		arm(accountHash, Math.max(0L, deadlineMillis - clock.nowMillis()));
	}

	/** Re-arms a failed probe only when this account was already in durable recovery. */
	synchronized boolean scheduleFallbackIfTracked(String accountHash, long baseDelayMillis)
	{
		if (store.get(accountHash) == null)
		{
			return false;
		}
		schedule(accountHash, baseDelayMillis);
		return true;
	}

	synchronized void activateAccount(String accountHash)
	{
		if (!accountHash.equals(activeAccountHash))
		{
			cancelTimerLocked();
			activeAccountHash = accountHash;
		}
		restore(accountHash);
	}

	synchronized void deactivate()
	{
		activeAccountHash = null;
		cancelTimerLocked();
	}

	synchronized void cancelTimer()
	{
		cancelTimerLocked();
	}

	synchronized void clear(String accountHash)
	{
		store.clear(accountHash);
		if (accountHash.equals(pendingAccountHash))
		{
			cancelTimerLocked();
		}
	}

	static long boundedDeterministicJitter(String accountHash, long delayMillis)
	{
		if (delayMillis <= 0)
		{
			return 0L;
		}
		long maximumJitter = Math.min(delayMillis / 10L, 5 * 60_000L);
		if (maximumJitter == 0L)
		{
			return delayMillis;
		}
		long hash = Integer.toUnsignedLong(accountHash == null ? 0 : accountHash.hashCode());
		long jitterMillis = hash % (maximumJitter + 1L);
		return saturatingAdd(delayMillis, jitterMillis);
	}

	private void arm(String accountHash, long delayMillis)
	{
		cancelTimerLocked();
		long taskGeneration = generation;
		pendingAccountHash = accountHash;
		pending = timer.schedule(() -> fire(accountHash, taskGeneration), delayMillis);
	}

	private void fire(String accountHash, long taskGeneration)
	{
		synchronized (this)
		{
			if (taskGeneration != generation
				|| !accountHash.equals(pendingAccountHash)
				|| !accountHash.equals(activeAccountHash))
			{
				return;
			}
			pending = null;
			pendingAccountHash = null;
			generation++;
		}
		retryAction.retry(accountHash);
	}

	private void cancelTimerLocked()
	{
		generation++;
		if (pending != null)
		{
			pending.cancel();
		}
		pending = null;
		pendingAccountHash = null;
	}

	private static long saturatingAdd(long left, long right)
	{
		try
		{
			return Math.addExact(left, right);
		}
		catch (ArithmeticException ignored)
		{
			return Long.MAX_VALUE;
		}
	}
}

package com.pbtracker;

import java.util.HashMap;
import java.util.Map;

/**
 * In-memory protection against repeatedly submitting an install credential
 * that the backend has already quarantined for recovery. State is keyed by
 * account hash so switching accounts never carries one player's block to
 * another. No credential or PB payload is retained here.
 */
final class InstallRecoveryCircuitBreaker
{
	private static final long RETRY_FAILURE_BACKOFF_MILLIS = 60_000L;
	private static final long DEFAULT_RETRY_MILLIS = 15 * 60_000L;
	private static final long MINIMUM_RETRY_MILLIS = 60_000L;
	private static final long MAXIMUM_RETRY_MILLIS = 60 * 60_000L;
	private static final long REJECTED_DEFAULT_RETRY_MILLIS = 6 * 60 * 60_000L;
	private static final long REJECTED_MINIMUM_RETRY_MILLIS = 60 * 60_000L;
	private static final long REJECTED_MAXIMUM_RETRY_MILLIS = 24 * 60 * 60_000L;

	private final Map<String, RecoveryState> states = new HashMap<>();

	synchronized AttemptDecision beginAutomaticAttempt(String accountHash, long nowMillis)
	{
		RecoveryState state = states.get(accountHash);
		if (state == null)
		{
			return AttemptDecision.allowed();
		}

		if (state.probeInFlight || nowMillis < state.blockedUntilMillis)
		{
			return AttemptDecision.blocked(state.response);
		}

		// The server-requested backoff has elapsed. Permit exactly one probe;
		// other automatic triggers remain blocked until it completes.
		state.probeInFlight = true;
		return AttemptDecision.allowed();
	}

	synchronized void recordMismatch(String accountHash, SyncClient.SyncErrorResponse response, long nowMillis)
	{
		long blockedUntilMillis;
		// Every recovery state may later be changed by an operator. Even a
		// rejected candidate gets a much slower dormant probe so a later
		// reactivation is discovered without making the player reinstall.
		try
		{
			blockedUntilMillis = Math.addExact(nowMillis, retryDelayMillis(response));
		}
		catch (ArithmeticException ignored)
		{
			blockedUntilMillis = Long.MAX_VALUE;
		}

		states.put(accountHash, new RecoveryState(response, blockedUntilMillis));
	}

	static long retryDelayMillis(SyncClient.SyncErrorResponse response)
	{
		boolean rejected = response != null && "RECOVERY_REJECTED".equals(response.code);
		long defaultDelay = rejected ? REJECTED_DEFAULT_RETRY_MILLIS : DEFAULT_RETRY_MILLIS;
		long minimumDelay = rejected ? REJECTED_MINIMUM_RETRY_MILLIS : MINIMUM_RETRY_MILLIS;
		long maximumDelay = rejected ? REJECTED_MAXIMUM_RETRY_MILLIS : MAXIMUM_RETRY_MILLIS;
		if (response == null || response.retryAfterSeconds == null)
		{
			return defaultDelay;
		}

		long requestedMillis;
		try
		{
			requestedMillis = Math.multiplyExact(response.retryAfterSeconds, 1_000L);
		}
		catch (ArithmeticException ignored)
		{
			requestedMillis = maximumDelay;
		}
		return Math.max(minimumDelay, Math.min(requestedMillis, maximumDelay));
	}

	/**
	 * Returns null when no automatic recovery retry is appropriate, otherwise
	 * the delay until the next single probe. An in-flight probe gets a short
	 * guard delay so unrelated automatic triggers cannot create a tight loop.
	 */
	synchronized Long millisUntilAutomaticRetry(String accountHash, long nowMillis)
	{
		RecoveryState state = states.get(accountHash);
		if (state == null || state.blockedUntilMillis == Long.MAX_VALUE)
		{
			return null;
		}
		if (state.probeInFlight)
		{
			return RETRY_FAILURE_BACKOFF_MILLIS;
		}
		return Math.max(0L, state.blockedUntilMillis - nowMillis);
	}

	synchronized void completeUnsuccessfulAutomaticAttempt(String accountHash, long nowMillis)
	{
		RecoveryState state = states.get(accountHash);
		if (state == null || !state.probeInFlight)
		{
			return;
		}

		state.probeInFlight = false;
		long retryAt;
		try
		{
			retryAt = Math.addExact(nowMillis, RETRY_FAILURE_BACKOFF_MILLIS);
		}
		catch (ArithmeticException ignored)
		{
			retryAt = Long.MAX_VALUE;
		}
		state.blockedUntilMillis = Math.max(state.blockedUntilMillis, retryAt);
	}

	synchronized void recordSuccess(String accountHash)
	{
		states.remove(accountHash);
	}

	synchronized void clear()
	{
		states.clear();
	}

	private static final class RecoveryState
	{
		private final SyncClient.SyncErrorResponse response;
		private long blockedUntilMillis;
		private boolean probeInFlight;

		private RecoveryState(SyncClient.SyncErrorResponse response, long blockedUntilMillis)
		{
			this.response = response;
			this.blockedUntilMillis = blockedUntilMillis;
		}
	}

	static final class AttemptDecision
	{
		final boolean allowed;
		final SyncClient.SyncErrorResponse response;

		private AttemptDecision(boolean allowed, SyncClient.SyncErrorResponse response)
		{
			this.allowed = allowed;
			this.response = response;
		}

		private static AttemptDecision allowed()
		{
			return new AttemptDecision(true, null);
		}

		private static AttemptDecision blocked(SyncClient.SyncErrorResponse response)
		{
			return new AttemptDecision(false, response);
		}
	}
}

package com.pbtracker;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Objects;

/**
 * Persists the last successful sync fingerprint per account,
 * so an unchanged payload doesn't repeat the POST across RuneLite restarts
 * (the in-memory AutomaticSyncDeduplicator only covers duplicates within a
 * single running session).
 * <p>
 * Stores through a small ConfigStore seam instead of RuneLite's real
 * ConfigManager directly, so this decision logic is unit-testable without
 * timing or mocking real RuneLite infrastructure.
 * <p>
 * Not atomic: {@link #matches} and {@link #record} are independent calls
 * against the underlying ConfigStore, so a caller doing
 * "check matches(), sync if false, then record()" from two racing threads
 * (e.g. a UI-triggered manual sync racing an automatic sync callback) could
 * interleave. This class has no internal mutable state of its own to
 * protect - configStore is the only field and it's final - so it adds no
 * locking; a caller that needs the check-then-act sequence to be atomic
 * must synchronize around its own call site.
 */
final class PersistedFingerprintStore
{
	private static final String KEY_PREFIX = "syncFingerprint.v1.";
	private static final String ACCOUNT_KEY_DOMAIN = "pbtracker.persisted-sync.account-key.v1\0";

	/** Minimal storage seam this class needs - implemented against RuneLite's real ConfigManager in PbTrackerPlugin. */
	interface ConfigStore
	{
		String get(String key);

		void set(String key, String value);

		void unset(String key);
	}

	private final ConfigStore configStore;

	PersistedFingerprintStore(ConfigStore configStore)
	{
		this.configStore = configStore;
	}

	static String configKeyFor(String accountHash)
	{
		// Unlike SyncFingerprint.compute (which normalizes a null
		// accountHash to "" since it must always produce some digest), this
		// class's whole purpose is being an unambiguous key store keyed BY
		// account - a null here would silently collide every caller that
		// passes one under the literal key "syncFingerprint.v1.null", so
		// fail loudly instead.
		Objects.requireNonNull(accountHash, "accountHash");
		return KEY_PREFIX + opaqueAccountSuffix(accountHash);
	}

	private static String opaqueAccountSuffix(String accountHash)
	{
		try
		{
			MessageDigest digest = MessageDigest.getInstance("SHA-256");
			digest.update(ACCOUNT_KEY_DOMAIN.getBytes(StandardCharsets.UTF_8));
			byte[] hashed = digest.digest(accountHash.getBytes(StandardCharsets.UTF_8));
			StringBuilder hex = new StringBuilder(hashed.length * 2);
			for (byte b : hashed)
			{
				hex.append(Character.forDigit((b >>> 4) & 0x0f, 16));
				hex.append(Character.forDigit(b & 0x0f, 16));
			}
			return hex.toString();
		}
		catch (NoSuchAlgorithmException e)
		{
			throw new IllegalStateException("SHA-256 not available", e);
		}
	}

	/** True if the given fingerprint matches what's stored for this account - i.e. nothing has changed since the last successful sync. */
	boolean matches(String accountHash, String fingerprint)
	{
		String stored = configStore.get(configKeyFor(accountHash));
		// A schema-version bump changes KEY_PREFIX, so an old value under a
		// different prefix simply won't be found here - this get() call
		// itself is the fail-open mechanism for a version change. A
		// same-prefix but otherwise-unparseable value also fails open,
		// since the stored format is a bare fingerprint string with no
		// further parsing to fail - any non-null, non-matching value just
		// falls through to the final inequality check below.
		return stored != null && stored.equals(fingerprint);
	}

	/** Records a fingerprint as the current known-successful state for this account. */
	void record(String accountHash, String fingerprint)
	{
		configStore.set(configKeyFor(accountHash), fingerprint);
	}

	/** Clears any stored fingerprint for this account (e.g. for install-recovery flows). */
	void clear(String accountHash)
	{
		configStore.unset(configKeyFor(accountHash));
	}
}

package com.pbtracker;

import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.LinkBrowser;

import javax.swing.BorderFactory;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import java.awt.BorderLayout;
import java.util.Locale;
import java.util.function.BiConsumer;
import java.util.function.Supplier;

/**
 * "My PBs" tab - auto-loads the logged-in player's own synced PBs, no typing
 * required (mirrors the in-game hiscore lookup convention of showing your
 * own stats by default).
 */
class MyPbsTab extends JPanel
{
	private final SyncClient syncClient;
	private final BiConsumer<String, String> onBossClickHandler;
	private final PbListPanel listPanel;
	private final JScrollPane scrollPane;
	private final JLabel viewOnWebsiteButton;
	private final LocalProfileLoadCoordinator localProfileLoadCoordinator;
	private final Supplier<String> accountHashSupplier;
	private long requestGeneration;
	private volatile String inFlightDisplayName;

	private String currentDisplayName;

	MyPbsTab(SyncClient syncClient, SpriteManager spriteManager, PbTrackerConfig config, BiConsumer<String, String> onBossClick, LocalProfileLoadCoordinator localProfileLoadCoordinator, Supplier<String> accountHashSupplier)
	{
		this.syncClient = syncClient;
		this.onBossClickHandler = onBossClick;
		this.localProfileLoadCoordinator = localProfileLoadCoordinator;
		this.accountHashSupplier = accountHashSupplier;
		this.listPanel = new PbListPanel(spriteManager, config);
		setLayout(new BorderLayout());
		setBackground(PbTrackerTheme.BG);

		viewOnWebsiteButton = buildViewOnWebsiteButton();
		JPanel header = new JPanel(new BorderLayout());
		header.setOpaque(false);
		header.add(viewOnWebsiteButton, BorderLayout.NORTH);
		header.add(buildRefreshButton(), BorderLayout.SOUTH);
		add(header, BorderLayout.NORTH);

		scrollPane = new JScrollPane(listPanel);
		scrollPane.setBorder(null);
		scrollPane.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scrollPane.getVerticalScrollBar().setUnitIncrement(16);
		add(scrollPane, BorderLayout.CENTER);

		listPanel.showMessage("Log in to see your PBs.");
	}

	/** Opens this player's PB tracker profile page on the website - same URL-building the config-driven "open profile on sync" feature already uses. */
	private JLabel buildViewOnWebsiteButton()
	{
		JLabel button = new JLabel("View My Profile on Website", SwingConstants.CENTER);
		button.setForeground(PbTrackerTheme.GOLD_LIGHT);
		button.setFont(FontManager.getRunescapeBoldFont());
		button.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 1, 0, PbTrackerTheme.PANEL_BORDER),
			BorderFactory.createEmptyBorder(8, 8, 8, 8)
		));
		button.setOpaque(true);
		button.setBackground(PbTrackerTheme.PANEL);
		PbTrackerPlugin.addRowClickListener(button, () ->
		{
			if (currentDisplayName != null)
			{
				LinkBrowser.browse(PbTrackerPlugin.buildProfileUrl(currentDisplayName));
			}
		});
		return button;
	}

	private JLabel buildRefreshButton()
	{
		JLabel button = new JLabel("Refresh My PBs", SwingConstants.CENTER);
		button.setForeground(PbTrackerTheme.GOLD_LIGHT);
		button.setFont(FontManager.getRunescapeSmallFont());
		button.setBorder(BorderFactory.createEmptyBorder(4, 8, 8, 8));
		button.setOpaque(true);
		button.setBackground(PbTrackerTheme.PANEL);
		PbTrackerPlugin.addRowClickListener(button, this::refresh);
		return button;
	}

	/** Every boss key this plugin knows about system-wide - forwarded to the list panel so untracked bosses can show a dash instead of being omitted. */
	void setAllBosses(java.util.List<String> bosses)
	{
		listPanel.setAllBosses(bosses);
	}

	/** Called on login (and whenever the panel is (re)opened) with the local player's name. */
	void load(String displayName)
	{
		String normalized = normalize(displayName);
		if (normalized.equals(inFlightDisplayName))
		{
			// Coordinator-level gating (Task 2) already prevents most
			// duplicate calls; this is a direct guard against any other
			// caller re-entering load() for the same name while a lookup
			// thread is still running.
			return;
		}
		inFlightDisplayName = normalized;

		currentDisplayName = displayName;
		listPanel.showMessage("Loading...");
		long request = ++requestGeneration;
		new Thread(() ->
		{
			SyncClient.PlayerLookupResult result = syncClient.lookupPlayer(displayName);
			SwingUtilities.invokeLater(() ->
			{
				if (normalized.equals(inFlightDisplayName))
				{
					inFlightDisplayName = null;
				}
				if (request != requestGeneration)
				{
					return;
				}
				switch (result.kind)
				{
					case FOUND:
						listPanel.showPlayer(result.player, onBossClickHandler);
						scrollToTop();
						boolean returnedUnderDifferentName = result.player == null
							|| !normalized.equals(normalize(result.player.displayName));
						if (localProfileLoadCoordinator.markLoaded(returnedUnderDifferentName))
						{
							load(displayName);
						}
						break;
					case NOT_FOUND:
						listPanel.showMessage("No synced PB data found yet - sync with the plugin first.");
						if (localProfileLoadCoordinator.markLoaded(true))
						{
							load(displayName);
						}
						break;
					case AMBIGUOUS:
						listPanel.showMessage("Multiple synced accounts share this name - check the website directly.");
						if (localProfileLoadCoordinator.markLoaded(true))
						{
							load(displayName);
						}
						break;
					case ERROR:
					default:
						listPanel.showMessage("Lookup failed - try again later.");
						if (localProfileLoadCoordinator.markError(System.currentTimeMillis()))
						{
							load(displayName);
						}
						break;
				}
			});
		}, "pbtracker-mypbs-lookup").start();
	}

	/** Goes through the coordinator's own manual-refresh decision (bypasses its "already loaded" cache but still coalesces a concurrent refresh at the coordinator level) so this path stays in sync with the coordinator's in-flight tracking instead of relying only on the local inFlightDisplayName guard. */
	void refresh()
	{
		if (currentDisplayName == null)
		{
			return;
		}
		String accountHash = accountHashSupplier.get();
		if (accountHash == null)
		{
			return;
		}
		LocalProfileLoadCoordinator.Decision decision = localProfileLoadCoordinator.onManualRefresh(accountHash, currentDisplayName);
		if (decision == LocalProfileLoadCoordinator.Decision.LOAD)
		{
			load(currentDisplayName);
		}
	}

	private void scrollToTop()
	{
		SwingUtilities.invokeLater(() -> scrollPane.getViewport().setViewPosition(new java.awt.Point(0, 0)));
	}

	void showLoggedOut()
	{
		requestGeneration++;
		inFlightDisplayName = null;
		currentDisplayName = null;
		listPanel.showMessage("Log in to see your PBs.");
	}

	void onSettingsChanged()
	{
		listPanel.onSettingsChanged();
	}

	private static String normalize(String displayName)
	{
		return displayName == null ? "" : displayName.trim().toLowerCase(Locale.ROOT);
	}
}

package com.pbtracker;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;
import java.util.Map;
import java.util.TreeMap;

/**
 * A SHA-256 digest identifying an exact (account, display name, PB set)
 * combination, used to decide whether an automatic sync payload has
 * actually changed since the last successful sync - including across
 * RuneLite restarts, unlike PbTrackerPlugin's in-memory
 * AutomaticSyncDeduplicator (which this class does not replace; the two
 * serve different lifetimes and PbTrackerPlugin.buildSyncFingerprint
 * deliberately excludes display name for its own, unrelated reason).
 */
final class SyncFingerprint
{
	private SyncFingerprint()
	{
	}

	static String compute(String accountHash, String displayName, Map<String, Double> pbs)
	{
		String hash = accountHash == null ? "" : accountHash;
		String normalizedName = normalizeDisplayName(displayName);

		StringBuilder canonical = new StringBuilder();
		canonical.append(hash.length()).append(':').append(hash).append('|');
		canonical.append(normalizedName.length()).append(':').append(normalizedName).append('|');
		for (Map.Entry<String, Double> entry : new TreeMap<>(pbs).entrySet())
		{
			String key = entry.getKey();
			canonical.append(key.length())
				.append(':')
				.append(key)
				.append('=')
				.append(Long.toHexString(Double.doubleToLongBits(entry.getValue())))
				.append(';');
		}

		return sha256Hex(canonical.toString());
	}

	private static String normalizeDisplayName(String displayName)
	{
		return displayName == null ? "" : displayName.trim().toLowerCase(Locale.ROOT);
	}

	private static String sha256Hex(String input)
	{
		try
		{
			MessageDigest digest = MessageDigest.getInstance("SHA-256");
			byte[] hash = digest.digest(input.getBytes(StandardCharsets.UTF_8));
			StringBuilder hex = new StringBuilder(hash.length * 2);
			for (byte b : hash)
			{
				hex.append(String.format("%02x", b));
			}
			return hex.toString();
		}
		catch (NoSuchAlgorithmException e)
		{
			// SHA-256 is a mandatory JDK algorithm (JLS/JCA guarantee) - this
			// is unreachable in practice, but fail loudly rather than
			// returning a bogus fingerprint that could silently disable the
			// skip-unchanged-sync optimization forever.
			throw new IllegalStateException("SHA-256 not available", e);
		}
	}
}

