	private static boolean isBareValue(String line)
	{
		return line.equals("-") || line.matches("[0-9:]+(?:\\.[0-9]+)?");
	}

	/**
	 * Extracts the account name from the Journalscroll TITLE widget's text -
	 * "The Exploits of Blitzen" or a bare "Blitzen" both yield "Blitzen".
	 * Returns null for blank/empty input, or for a known generic Adventure
	 * Log page label (GENERIC_JOURNAL_TITLES) that isn't actually an account
	 * name - both cases mean "couldn't determine an owner", which callers
	 * treat as "don't block the sync" rather than a mismatch.
	 */
	static String extractAdventureLogOwnerName(String titleText)
	{
		if (titleText == null)
		{
			return null;
		}
		String trimmed = titleText.trim();
		if (trimmed.isEmpty())
		{
			return null;
		}
		Matcher matcher = JOURNAL_TITLE_PATTERN.matcher(trimmed);
		if (!matcher.matches())
		{
			return null;
		}
		String name = matcher.group("name").trim();
		if (GENERIC_JOURNAL_TITLES.contains(name.toLowerCase()))
		{
			return null;
		}
		return name;
	}

	/**
	 * Turns a heading ("Theatre of Blood") and a raw descriptor ("Room time -
	 * (Team size: 3 player)") into a clean, unambiguous sync key like
	 * "Theatre of Blood - Fastest Room (3 player)". Bare "kill"/"run" (no
	 * team size, single-stat bosses) just use the heading as-is.
	 */
	private static String buildKey(String heading, String descriptor)
	{
		String normalizedHeading = canonicalBossKey(heading);
		if (descriptor.equals("kill") || descriptor.equals("run"))
		{
			return normalizedHeading;
		}

		String label;
		String remainder;
		if (descriptor.startsWith("Room time"))
		{
			label = "Fastest Room";
			remainder = descriptor.substring("Room time".length());
		}
		else if (descriptor.startsWith("Wave time"))
		{
			label = "Fastest Wave";
			remainder = descriptor.substring("Wave time".length());
		}
		else if (descriptor.startsWith("Overall time"))
		{
			label = "Fastest Overall";
			remainder = descriptor.substring("Overall time".length());
		}
		else if (descriptor.startsWith("kill"))
		{
			label = "Fastest Overall";
			remainder = descriptor.substring("kill".length());
		}
		else if (descriptor.startsWith("run"))
		{
			label = "Fastest Overall";
			remainder = descriptor.substring("run".length());
		}
		else
		{
			// Unrecognized shape - keep the raw descriptor rather than
			// silently dropping the record.
			label = descriptor;
			remainder = "";
		}

		String detail = remainder
			.replace("- (Team size:", "")
			.replaceAll("[()]", "")
			.trim();

		return normalizedHeading + " - " + label + (detail.isEmpty() ? "" : " (" + detail + ")");
	}

	private static Double parseTimeString(String timeString)
	{
		try
		{
			String[] parts = timeString.split(":");
			if (parts.length == 2)
			{
				return Integer.parseInt(parts[0]) * 60 + Double.parseDouble(parts[1]);
			}
			else if (parts.length == 3)
			{
				return Integer.parseInt(parts[0]) * 3600 + Integer.parseInt(parts[1]) * 60 + Double.parseDouble(parts[2]);
			}
			return Double.parseDouble(timeString);
		}
		catch (NumberFormatException ex)
		{
			return null;
		}
	}

	private void syncAll(boolean force)
	{
		String profileKey = configManager.getRSProfileKey();
		if (profileKey == null)
		{
			setStatus("Not logged in yet - log in, then try again.");
			return;
		}

		List<String> bossKeys = configManager.getRSProfileConfigurationKeys(CONFIG_GROUP, profileKey, "");

		Map<String, Double> raw = new HashMap<>();
		for (String boss : bossKeys)
		{
			Double seconds = configManager.getRSProfileConfiguration(CONFIG_GROUP, boss, double.class);
			if (seconds != null)
			{
				raw.put(boss, seconds);
			}
		}

		// Skip raid/team-size variants (e.g. "chambers of xeric 2 players") -
		// those are synced with proper Room/Overall labels by the Adventure
		// Log parser instead, so sending the raw version here would just
		// create a duplicate, differently-named row for the same record.
		Map<String, Double> pbs = new HashMap<>();
		for (Map.Entry<String, Double> entry : raw.entrySet())
		{
			String key = entry.getKey();
			if (shouldSyncRawPersonalBest(key))
			{
				pbs.put(canonicalBossKey(key), entry.getValue());
			}
		}

		String unsyncedNote = buildUnsyncedDuplicatesNote(raw);

		if (pbs.isEmpty())
		{
			setStatus(unsyncedNote != null
				? "No personal bests found yet. " + unsyncedNote
				: "No personal bests found yet - go kill something!");
			return;
		}

		syncPbs(pbs, unsyncedNote, force, "Syncing " + pbs.size() + " PB(s)...");
	}

	/**
	 * Jad/Zuk/Colosseum/Hueycoatl are deliberately excluded from live and bulk
	 * sync (see looksLikeRaidVariant) so the Adventure Log parser can supply
	 * them with a properly-labelled name instead. But that parser only runs
	 * when the player manually opens the in-game Adventure Log Counters page
	 * - if they never do, those records would otherwise just never sync.
	 * Returns a status note listing any such records that are sitting unsynced
	 * right now, or null if there's nothing to flag.
	 */
	private String buildUnsyncedDuplicatesNote(Map<String, Double> raw)
	{
		List<String> unsynced = new ArrayList<>();
		for (Map.Entry<String, String> entry : KNOWN_DUPLICATE_RAW_KEYS.entrySet())
		{
			String heading = entry.getValue();
			if (raw.containsKey(entry.getKey()) && !syncedAdventureLogHeadings.contains(heading.toLowerCase()))
			{
				unsynced.add(heading);
			}
		}

		if (unsynced.isEmpty())
		{
			return null;
		}

		return "Not synced yet: " + String.join(", ", unsynced) + " - open Adventure Log > Counters once to sync.";
	}

	/**
	 * Diagnostic dump of every raw personalbest.* value RuneLite has cached,
	 * independent of whether our own sync logic would forward it - lets a
	 * player prove what RuneLite actually has locally without relying on
	 * per-boss !pb chat commands. Copies the report to the clipboard rather
	 * than syncing anything.
	 */
	private void dumpRawPersonalBests()
	{
		String profileKey = configManager.getRSProfileKey();
		if (profileKey == null)
		{
			setStatus("Not logged in yet - log in, then try again.");
			return;
		}

		List<String> bossKeys = configManager.getRSProfileConfigurationKeys(CONFIG_GROUP, profileKey, "");

		Map<String, Double> raw = new HashMap<>();
		for (String boss : bossKeys)
		{
			Double seconds = configManager.getRSProfileConfiguration(CONFIG_GROUP, boss, double.class);
			if (seconds != null)
			{
				raw.put(boss, seconds);
			}
		}

		String report = buildRawPbReport(raw);
		Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(report), null);
		setStatus("Copied " + raw.size() + " raw PB value(s) to clipboard.");
	}

	/**
	 * Opens the current account's PB tracker profile page in the system
	 * browser - mirrors Wise Old Man's "open my profile" feature.
	 */
	private void openProfile()
	{
		if (client.getLocalPlayer() == null || client.getLocalPlayer().getName() == null)
		{
			setStatus("Not logged in yet - log in, then try again.");
			return;
		}

		String url = buildProfileUrl(client.getLocalPlayer().getName());
		LinkBrowser.browse(url);
	}

	/**
	 * Pure formatting of a raw personalbest.* map into a diagnostic report,
	 * annotating each entry with whether shouldSyncRawPersonalBest() would
	 * forward it as-is or is gating it (and why) - kept static and free of
	 * ConfigManager/AWT so it's directly unit-testable.
	 */
	static String buildRawPbReport(Map<String, Double> raw)
	{
		Map<String, Double> sorted = new TreeMap<>(raw);
		StringBuilder report = new StringBuilder();
		for (Map.Entry<String, Double> entry : sorted.entrySet())
		{
			String key = entry.getKey();
			report.append("personalbest.").append(key).append(" = ").append(entry.getValue()).append(" -> ");

			if (shouldSyncRawPersonalBest(key))
			{
				report.append("synced as \"").append(canonicalBossKey(key)).append('"');
			}
			else
			{
				String heading = KNOWN_DUPLICATE_RAW_KEYS.get(key.toLowerCase());
				if (heading != null)
				{
					report.append("SKIPPED (gated, waiting on Adventure Log Counters -> \"").append(heading).append("\")");
				}
				else
				{
					report.append("SKIPPED (raid/team-size variant, waiting on Adventure Log Counters)");
				}
			}

			report.append('\n');
		}

		return report.toString();
	}

	/**
	 * Pure URL-building for the "open my profile" action - kept static and
	 * side-effect-free (no Client, no LinkBrowser) so it's directly
	 * unit-testable, same pattern as buildRawPbReport.
	 */
	static String buildProfileUrl(String playerName)
	{
		// URLEncoder implements HTML form encoding (encodes a space as "+"),
		// but the frontend decodes the path segment with JavaScript's
		// decodeURIComponent, which does NOT treat "+" as a space - only
		// %-escapes are decoded. Replacing "+" with "%20" after encoding
		// matches what JavaScript's encodeURIComponent produces for a space,
		// so the two sides agree.
		String encoded = URLEncoder.encode(playerName, StandardCharsets.UTF_8).replace("+", "%20");
		return PROFILE_SITE_URL + "/player/" + encoded;
	}

	private void syncPbs(Map<String, Double> pbs)
	{
		syncPbs(pbs, null, false, null);
	}

	private void syncPbs(Map<String, Double> pbs, String statusNote, boolean force, String startedStatus)
	{
		if (pbs.isEmpty() || client.getLocalPlayer() == null || client.getLocalPlayer().getName() == null)
		{
			return;
		}

		String name = client.getLocalPlayer().getName();
		String hash = accountHash != null ? accountHash : String.valueOf(client.getAccountHash());
		String suffix = statusNote != null ? " " + statusNote : "";
		String fingerprint = usesAutomaticSyncGuards(force) ? buildSyncFingerprint(hash, pbs) : null;
		// Always computed (even when force=true) so the successful-response
		// callback below has a single, unconditional value to record - no
		// ternary needed there, and the extra SHA-256 over a short string is
		// negligible on the manual-sync path.
		String persistedFingerprint = SyncFingerprint.compute(hash, name, pbs);

		if (fingerprint != null && !automaticSyncDeduplicator.tryStart(fingerprint, System.currentTimeMillis()))
		{
			log.debug("Suppressing duplicate automatic PB sync for {} PB(s)", pbs.size());
			return;
		}
		if (fingerprint != null)
		{
			InstallRecoveryCircuitBreaker.AttemptDecision decision =
				installRecoveryCircuitBreaker.beginAutomaticAttempt(hash, System.currentTimeMillis());
			if (!decision.allowed)
			{
				// The deduplicator claimed this payload before the recovery gate
				// was checked. Release it as unsuccessful so a later permitted
				// recovery probe is never mistaken for an in-flight/successful send.
				automaticSyncDeduplicator.finish(fingerprint, false, System.currentTimeMillis());
				setStatusIfCurrent(hash, formatInstallRecoveryStatus(decision.response));
				Long retryDelayMillis = installRecoveryCircuitBreaker.millisUntilAutomaticRetry(
					hash, System.currentTimeMillis());
				if (retryDelayMillis != null)
				{
					recoveryRetryCoordinator.ensureScheduled(hash, retryDelayMillis);
				}
				return;
			}
		}
		if (persistentSyncCoordinator.shouldSkip(force, hash, persistedFingerprint))
		{
			log.debug("Skipping automatic PB sync for {} PB(s): unchanged since last successful sync", pbs.size());
			if (fingerprint != null)
			{
				automaticSyncDeduplicator.finish(fingerprint, false, System.currentTimeMillis());
				installRecoveryCircuitBreaker.completeUnsuccessfulAutomaticAttempt(hash, System.currentTimeMillis());
				scheduleRecoveryRetry(hash);
			}
			setStatusIfCurrent(hash, "No PB changes since last successful sync" + suffix);
			return;
		}
		if (startedStatus != null)
		{
			setStatusIfCurrent(hash, startedStatus);
		}

		try
		{
			syncClient.sync(hash, name, pbs, installSecret, new Callback()
			{
				@Override
				public void onFailure(Call call, IOException e)
				{
					persistentSyncCoordinator.complete(
						false, hash, accountHash, persistedFingerprint, null);
					if (fingerprint != null)
					{
						automaticSyncDeduplicator.finish(fingerprint, false, System.currentTimeMillis());
						installRecoveryCircuitBreaker.completeUnsuccessfulAutomaticAttempt(hash, System.currentTimeMillis());
						scheduleRecoveryRetry(hash);
					}
					log.warn("PB sync failed", e);
					setStatusIfCurrent(hash, "Sync failed: " + e.getMessage());
				}

				@Override
				public void onResponse(Call call, Response response)
				{
					boolean successful = response.isSuccessful();
					try
					{
						if (successful)
						{
							installRecoveryCircuitBreaker.recordSuccess(hash);
							recoveryRetryCoordinator.clear(hash);
							setStatusIfCurrent(hash, "Last updated: " + TIMESTAMP_FORMAT.format(LocalDateTime.now()) + suffix);
							SyncClient.SyncResponseDto outcome = syncClient.parseSyncResponse(response);
							if (persistentSyncCoordinator.complete(
								true, hash, accountHash, persistedFingerprint, outcome))
							{
								if (sidePanel != null)
								{
									loadLocalPlayerPanelWhenReady(0, hash);
								}
							}
						}
						else if (response.code() == 409)
						{
							persistentSyncCoordinator.complete(
								false, hash, accountHash, persistedFingerprint, null);
							// A credential mismatch starts or advances install recovery.
							// Discard the previously successful payload marker so the one
							// automatic probe permitted after the server backoff cannot be
							// suppressed by the persisted unchanged-payload gate.
							persistentSyncCoordinator.invalidateFingerprint(hash);
							SyncClient.SyncErrorResponse syncError = syncClient.parseSyncErrorResponse(response);
							installRecoveryCircuitBreaker.recordMismatch(hash, syncError, System.currentTimeMillis());
							setStatusIfCurrent(hash, formatInstallRecoveryStatus(syncError));
							scheduleRecoveryRetry(hash);
						}
						else
						{
							persistentSyncCoordinator.complete(
								false, hash, accountHash, persistedFingerprint, null);
							if (fingerprint != null)
							{
								installRecoveryCircuitBreaker.completeUnsuccessfulAutomaticAttempt(hash, System.currentTimeMillis());
								scheduleRecoveryRetry(hash);
							}
							setStatusIfCurrent(hash, "Server responded with error " + response.code());
						}
					}
					finally
					{
						if (fingerprint != null)
						{
							automaticSyncDeduplicator.finish(fingerprint, successful, System.currentTimeMillis());
						}
						response.close();
					}
				}
			});
		}
		catch (RuntimeException ex)
		{
			persistentSyncCoordinator.complete(
				false, hash, accountHash, persistedFingerprint, null);
			if (fingerprint != null)
			{
				automaticSyncDeduplicator.finish(fingerprint, false, System.currentTimeMillis());
				installRecoveryCircuitBreaker.completeUnsuccessfulAutomaticAttempt(hash, System.currentTimeMillis());
				scheduleRecoveryRetry(hash);
			}
			throw ex;
		}
	}

	static boolean usesAutomaticSyncGuards(boolean force)
	{
		return !force;
	}

	private void setStatusIfCurrent(String capturedAccountHash, String text)
	{
		if (shouldApplyAccountScopedUpdate(
			capturedAccountHash,
			accountHash,
			String.valueOf(client.getAccountHash()),
			client.getGameState() == GameState.LOGGED_IN))
		{
			setStatus(text);
		}
	}

	static boolean shouldApplyAccountScopedUpdate(
		String capturedAccountHash,
		String trackedAccountHash,
		String clientAccountHash,
		boolean loggedIn)
	{
		return loggedIn
			&& capturedAccountHash != null
			&& capturedAccountHash.equals(trackedAccountHash)
			&& capturedAccountHash.equals(clientAccountHash);
	}

	static String formatInstallRecoveryStatus(SyncClient.SyncErrorResponse response)
	{
		if ("RECOVERY_REJECTED".equals(response.code))
		{
			return "This RuneLite installation was not approved. Sync will check again periodically.";
		}

		switch (response.code)
		{
			case "RECOVERY_CONTESTED":
			case "RECOVERY_INVALIDATION_FAILED":
				return "This RuneLite installation is awaiting review. Sync will resume automatically when resolved.";
			default:
				return "Verifying this RuneLite installation. Sync will resume automatically.";
		}
	}

	/**
	 * Replayed syncs and malformed responses cannot establish a new profile
	 * state. A valid non-replayed zero-update response is still passed to the
	 * coordinator, which only refreshes it when the prior lookup showed that
	 * profile metadata may have been stale.
	 */
	static boolean isNonDeduplicatedSuccessfulSyncOutcome(SyncClient.SyncResponseDto outcome)
	{
		return outcome != null
			&& (outcome.updated != null || outcome.metadataChanged != null)
			&& !Boolean.TRUE.equals(outcome.deduplicated);
	}

	/** Returns true only when the response itself reports a profile-affecting change. */
	static boolean shouldRefreshLocalProfileAfterSync(SyncClient.SyncResponseDto outcome)
	{
		return isNonDeduplicatedSuccessfulSyncOutcome(outcome)
			&& (outcome.updated != null && outcome.updated > 0
				|| Boolean.TRUE.equals(outcome.metadataChanged));
	}

	/**
	 * Builds an order-independent identity for an exact account/PB payload.
	 * Key lengths and the raw IEEE-754 value bits make each component
	 * unambiguous without putting a secret or display name into the key.
	 */
	static String buildSyncFingerprint(String accountHash, Map<String, Double> pbs)
	{
		StringBuilder fingerprint = new StringBuilder(accountHash == null ? "" : accountHash).append('|');
		for (Map.Entry<String, Double> entry : new TreeMap<>(pbs).entrySet())
		{
			String key = entry.getKey();
			fingerprint.append(key.length())
				.append(':')
				.append(key)
				.append('=')
				.append(Long.toHexString(Double.doubleToLongBits(entry.getValue())))
				.append(';');
		}
		return fingerprint.toString();
	}

	static final class LoginSyncSession
	{
		static final long ALREADY_SCHEDULED = -1;
		private String accountHash;
		private long sessionId;

		long markLoggedIn(String currentAccountHash)
		{
			if (currentAccountHash.equals(accountHash))
			{
				return ALREADY_SCHEDULED;
			}
			accountHash = currentAccountHash;
			return ++sessionId;
		}

		boolean isCurrent(String expectedAccountHash, long expectedSessionId)
		{
			return expectedSessionId == sessionId && expectedAccountHash.equals(accountHash);
		}

		void reset()
		{
			accountHash = null;
			sessionId++;
		}
	}

	static final class AutomaticSyncDeduplicator
	{
		private final long duplicateWindowMillis;
		private final Set<String> inFlight = new HashSet<>();
		private final Map<String, Long> recentlySuccessful = new HashMap<>();

		AutomaticSyncDeduplicator(long duplicateWindowMillis)
		{
			this.duplicateWindowMillis = duplicateWindowMillis;
		}

		synchronized boolean tryStart(String fingerprint, long nowMillis)
		{
			recentlySuccessful.entrySet().removeIf(
				entry -> nowMillis - entry.getValue() >= duplicateWindowMillis);
			if (inFlight.contains(fingerprint) || recentlySuccessful.containsKey(fingerprint))
			{
				return false;
			}
			inFlight.add(fingerprint);
			return true;
		}

		synchronized void finish(String fingerprint, boolean successful, long nowMillis)
		{
			inFlight.remove(fingerprint);
			if (successful)
			{
				recentlySuccessful.put(fingerprint, nowMillis);
			}
		}
	}
}

package com.pbtracker;

import java.util.List;
import java.util.regex.Pattern;

/**
 * Display-side mirror of the backend/frontend tracked-boss allowlist. The
 * backend rejects new untracked PBs, but filtering here also keeps historical
 * rows from resurfacing in the side panel.
 */
final class TrackedBosses
{
	private static final Pattern DOOM_TIMED_DELVE = Pattern.compile(
		"^doom of mokhaiotl - delve (?:[1-8]|8\\+)$"
	);

	private static final List<String> PREFIXES = List.of(
		"alchemical hydra", "amoxliatl", "araxxor", "chambers of xeric",
		"corrupted gauntlet", "gauntlet", "duke sucellus", "fortis colosseum",
		"sol heredit", "grotesque guardians", "hespori", "hueycoatl", "leviathan",
		"maggot king", "mimic", "nex", "phosani's nightmare", "nightmare",
		"phantom muspah", "royal titans", "shellbane gryphon", "theatre of blood",
		"tzhaar-ket-rak", "tzhaar fight cave", "fight caves", "tztok-jad",
		"tzkal-zuk", "inferno", "vardorvis", "vorkath", "whisperer", "yama",
		"zulrah", "tombs of amascut"
	);

	private TrackedBosses()
	{
	}

	static boolean isTracked(String boss)
	{
		if (boss == null)
		{
			return false;
		}
		String normalized = boss.trim().toLowerCase();
		if (normalized.startsWith("the "))
		{
			normalized = normalized.substring(4);
		}
		if (isDoomTimedDelve(normalized))
		{
			return true;
		}
		for (String prefix : PREFIXES)
		{
			if (normalized.startsWith(prefix))
			{
				return true;
			}
		}
		return false;
	}

	static boolean isDoomTimedDelve(String boss)
	{
		return boss != null && DOOM_TIMED_DELVE.matcher(boss.trim().toLowerCase()).matches();
	}
}

