package com.pbtracker;

import lombok.extern.slf4j.Slf4j;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.FontManager;

import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextArea;
import javax.swing.Scrollable;
import javax.swing.SwingConstants;
import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.function.BiConsumer;

/**
 * Renders a player's synced PBs as two collapsible sections: "Top Bosses"
 * (their 5 best-ranked performances) and "All Bosses" (every boss this
 * plugin knows about - with a dash for anything the player hasn't recorded
 * a time for yet, not just the ones they have). Reused by both the "My PBs"
 * and "Player Search" tabs.
 * <p>
 * Implements Scrollable so the enclosing JScrollPane's JViewport clamps this
 * panel's width to the actual visible width instead of using its raw (and,
 * because of the wrapped JTextArea labels, misleadingly wide) preferred
 * size - without this, a plain JPanel isn't Scrollable-aware, so the
 * viewport just takes the view's inflated preferred width verbatim, which is
 * what let long headings force the whole panel wider instead of wrapping.
 */
@Slf4j
class PbListPanel extends JPanel implements Scrollable
{
	private final SpriteManager spriteManager;
	private final PbTrackerConfig config;
	private final JPanel rowsContainer = new JPanel();

	private List<String> allBosses = List.of();
	private final Set<String> expandedHeadings = new HashSet<>();
	private boolean topBossesSectionExpanded = true;
	private boolean allBossesSectionExpanded = true;

	// Rebuilt fresh on every render - lets the expand/collapse click handler
	// find where its row landed in the just-rebuilt layout, since rerender()
	// tears down and recreates every row rather than moving the existing one.
	private final java.util.Map<String, Component> rowsByExpandKey = new java.util.HashMap<>();

	private SyncClient.PlayerLookupResponse lastPlayer;
	private BiConsumer<String, String> lastOnBossClick;

	PbListPanel(SpriteManager spriteManager, PbTrackerConfig config)
	{
		this.spriteManager = spriteManager;
		this.config = config;
		setLayout(new BorderLayout());
		setBackground(PbTrackerTheme.BG);

		rowsContainer.setLayout(new GridBagLayout());
		rowsContainer.setBackground(PbTrackerTheme.BG);
		add(rowsContainer, BorderLayout.NORTH);
	}

	/** Called when the "Show Overall/Room times" settings change, to re-render with the new filter applied. */
	void onSettingsChanged()
	{
		rerender();
	}

	/** Every boss key this plugin knows about system-wide - used to show a dash row for anything this player hasn't done yet. */
	void setAllBosses(List<String> allBosses)
	{
		this.allBosses = allBosses;
		rerender();
	}

	@Override
	public Dimension getPreferredScrollableViewportSize()
	{
		return getPreferredSize();
	}

	@Override
	public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
	{
		return 16;
	}

	@Override
	public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
	{
		return visibleRect.height;
	}

	@Override
	public boolean getScrollableTracksViewportWidth()
	{
		return true;
	}

	@Override
	public boolean getScrollableTracksViewportHeight()
	{
		return false;
	}

	void showMessage(String text)
	{
		lastPlayer = null;
		rowsContainer.removeAll();
		JLabel label = new JLabel("<html><center>" + escapeHtml(text) + "</center></html>");
		label.setForeground(PbTrackerTheme.TEXT_DIM);
		label.setHorizontalAlignment(SwingConstants.CENTER);
		label.setBorder(BorderFactory.createEmptyBorder(16, 8, 16, 8));
		addFullWidthRow(label);
		revalidate();
		repaint();
	}

	static String escapeHtml(String text)
	{
		return text.replace("&", "&amp;")
			.replace("<", "&lt;")
			.replace(">", "&gt;")
			.replace("\"", "&quot;")
			.replace("'", "&#39;");
	}

	/** One row's worth of display data, merging the global "every known boss" template with this player's actual recorded times. */
	private static final class DisplayRow
	{
		final String heading;
		final String iconKey;
		final String primaryName;
		final String subtitle;
		final boolean hasData;
		final double timeSeconds;
		final int rank;
		final String clickKey;
		final List<BossGroups.PlayerRaidVariant> variants;
		final double topTimeSeconds;
		final int topRank;
		final String topClickKey;

		DisplayRow(String heading, String iconKey, String primaryName, String subtitle, boolean hasData,
			double timeSeconds, int rank, String clickKey, List<BossGroups.PlayerRaidVariant> variants)
		{
			this(heading, iconKey, primaryName, subtitle, hasData, timeSeconds, rank, clickKey, variants,
				timeSeconds, rank, clickKey);
		}

		DisplayRow(String heading, String iconKey, String primaryName, String subtitle, boolean hasData,
			double timeSeconds, int rank, String clickKey, List<BossGroups.PlayerRaidVariant> variants,
			double topTimeSeconds, int topRank, String topClickKey)
		{
			this.heading = heading;
			this.iconKey = iconKey;
			this.primaryName = primaryName;
			this.subtitle = subtitle;
			this.hasData = hasData;
			this.timeSeconds = timeSeconds;
			this.rank = rank;
			this.clickKey = clickKey;
			this.variants = variants;
			this.topTimeSeconds = topTimeSeconds;
			this.topRank = topRank;
			this.topClickKey = topClickKey;
		}

		DisplayRow forTopBosses()
		{
			return new DisplayRow(heading, iconKey, primaryName, subtitle, hasData,
				topTimeSeconds, topRank, topClickKey, variants);
		}
	}

	/**
	 * @param onBossClick called with (bossKey, displayName) when a row is
	 *                     clicked - callers use this to jump to that boss's
	 *                     leaderboard, highlighted on the clicked player.
	 */
	void showPlayer(SyncClient.PlayerLookupResponse player, BiConsumer<String, String> onBossClick)
	{
		lastPlayer = player;
		lastOnBossClick = onBossClick;
		rowsContainer.removeAll();
		rowsByExpandKey.clear();

		if (player.pbs == null || player.pbs.isEmpty())
		{
			showMessage(player.displayName + " has synced, but has no recorded PBs yet.");
			return;
		}

		List<BossGroups.PlayerPb> pbs = new ArrayList<>();
		for (SyncClient.PbEntryDto pb : player.pbs)
		{
			pbs.add(new BossGroups.PlayerPb(pb.boss, pb.timeSeconds, pb.rank, pb.updatedAt));
		}
		BossGroups.GroupedPlayerPbs grouped = BossGroups.groupPlayerRaidPbs(pbs);

		List<DisplayRow> allRows = buildAllRows(grouped);

		List<DisplayRow> ranked = new ArrayList<>();
		for (DisplayRow row : allRows)
		{
			if (row.hasData)
			{
				ranked.add(row);
			}
		}
		ranked.sort(Comparator.comparingInt(r -> r.topRank));

		addSectionHeader("Top Bosses", topBossesSectionExpanded, () -> topBossesSectionExpanded = !topBossesSectionExpanded);
		if (topBossesSectionExpanded)
		{
			for (int i = 0; i < Math.min(5, ranked.size()); i++)
			{
				addDisplayRow("top", ranked.get(i).forTopBosses(), player.displayName, onBossClick);
			}
		}

		addSectionHeader("All Bosses", allBossesSectionExpanded, () -> allBossesSectionExpanded = !allBossesSectionExpanded);
		if (allBossesSectionExpanded)
		{
			List<DisplayRow> sorted = new ArrayList<>(allRows);
			sorted.sort(Comparator.comparing(r -> r.primaryName.toLowerCase()));
			for (DisplayRow row : sorted)
			{
				addDisplayRow("all", row, player.displayName, onBossClick);
			}
		}

		revalidate();
		repaint();
	}

	private void rerender()
	{
		if (lastPlayer != null)
		{
			showPlayer(lastPlayer, lastOnBossClick);
		}
	}

	/** Every raid heading + flat boss key this plugin knows about, merged with this player's actual PBs (dash if they have none). */
	private List<DisplayRow> buildAllRows(BossGroups.GroupedPlayerPbs grouped)
	{
		java.util.Map<String, BossGroups.PlayerRaidGroup> playerGroupsByHeading = new java.util.LinkedHashMap<>();
		for (BossGroups.PlayerRaidGroup g : grouped.groups)
		{
			playerGroupsByHeading.put(g.heading, g);
		}
		java.util.Map<String, BossGroups.PlayerPb> playerFlatByKey = new java.util.LinkedHashMap<>();
		for (BossGroups.PlayerPb pb : grouped.flat)
		{
			playerFlatByKey.put(pb.boss.trim().toLowerCase(), pb);
		}

		List<DisplayRow> rows = new ArrayList<>();

		List<BossGroups.RaidGroup> templateGroups = BossGroups.groupedRaidGroups(allBosses);
		Set<String> templateHeadings = new HashSet<>();
		for (BossGroups.RaidGroup template : templateGroups)
		{
			templateHeadings.add(template.heading);
			rows.add(buildRaidRow(template.heading, template.variants.get(0).key, playerGroupsByHeading.get(template.heading)));
		}
		// A player might have a PB for a heading the global list hasn't caught up to yet - don't drop it.
		for (BossGroups.PlayerRaidGroup playerGroup : grouped.groups)
		{
			if (!templateHeadings.contains(playerGroup.heading))
			{
				rows.add(buildRaidRow(playerGroup.heading, playerGroup.summary.key, playerGroup));
			}
		}

		Set<String> templateFlatKeys = new HashSet<>();
		for (String key : BossGroups.getFlatBossKeys(allBosses))
		{
			String norm = key.trim().toLowerCase();
			templateFlatKeys.add(norm);
			rows.add(buildFlatRow(key, playerFlatByKey.get(norm)));
		}
		for (BossGroups.PlayerPb pb : grouped.flat)
		{
			if (!templateFlatKeys.contains(pb.boss.trim().toLowerCase()))
			{
				rows.add(buildFlatRow(pb.boss, pb));
			}
		}

		return rows;
	}

	private DisplayRow buildRaidRow(String heading, String templateClickKey, BossGroups.PlayerRaidGroup playerGroup)
	{
		int dashIdx = heading.indexOf(" - ");
		String primaryName = dashIdx >= 0 ? heading.substring(0, dashIdx) : heading;
		String subtitle = dashIdx >= 0 ? heading.substring(dashIdx + 3) : null;

		if (playerGroup == null)
		{
			return new DisplayRow(heading, heading, primaryName, subtitle, false, 0, 0, templateClickKey, null);
		}
		List<BossGroups.PlayerRaidVariant> variants = playerGroup.variants.size() > 1 ? playerGroup.variants : null;
		BossGroups.PlayerRaidVariant bestRanked = BossGroups.pickBestRanked(playerGroup.variants);
		return new DisplayRow(heading, heading, primaryName, subtitle, true,
			playerGroup.summary.timeSeconds, playerGroup.summary.rank, playerGroup.summary.key, variants,
			bestRanked.timeSeconds, bestRanked.rank, bestRanked.key);
	}

	private DisplayRow buildFlatRow(String key, BossGroups.PlayerPb pb)
	{
		String primaryName = PbTrackerPlugin.titleCase(key);
		if (pb == null)
		{
			return new DisplayRow(key, key, primaryName, null, false, 0, 0, key, null);
		}
		return new DisplayRow(key, key, primaryName, null, true, pb.timeSeconds, pb.rank, pb.boss, null);
	}

	private void addSectionHeader(String text, boolean expanded, Runnable onToggle)
	{
		JPanel row = new JPanel(new BorderLayout());
		row.setBackground(PbTrackerTheme.BG);
		row.setBorder(BorderFactory.createEmptyBorder(10, 8, 6, 8));

		JLabel label = new JLabel(text);
		label.setForeground(PbTrackerTheme.TEXT);
		label.setFont(FontManager.getRunescapeBoldFont().deriveFont(FontManager.getRunescapeBoldFont().getSize2D() + 2f));
		row.add(label, BorderLayout.WEST);

		JLabel chevron = new JLabel(expanded ? "v" : ">");
		chevron.setForeground(PbTrackerTheme.TEXT_DIM);
		chevron.setFont(label.getFont());
		row.add(chevron, BorderLayout.EAST);
		PbTrackerPlugin.addRowClickListener(row, () ->
		{
			onToggle.run();
			rerender();
		});

		addFullWidthRow(row);
	}

	/**
	 * The whole row is the click target - if it has a team-size breakdown,
	 * clicking toggles that breakdown open beneath it in place (matching
	 * "collapsable to see the other PBs under the boss"); otherwise it jumps
	 * straight to that boss's leaderboard, same as before.
	 */
	/**
	 * @param section distinguishes "Top Bosses" from "All Bosses" so the same
	 *                raid heading (e.g. Chambers Of Xeric) can be expanded
	 *                independently in each section - previously both shared
	 *                one key, so expanding it in one section expanded it in
	 *                the other too.
	 */
	private void addDisplayRow(String section, DisplayRow row, String displayName, BiConsumer<String, String> onBossClick)
	{
		String expandKey = section + ":" + row.heading;
		boolean expandable = row.variants != null;
		boolean expanded = expandable && expandedHeadings.contains(expandKey);

		JPanel outer = new JPanel(new BorderLayout(8, 0));
		outer.setBackground(PbTrackerTheme.PANEL);
		outer.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 1, 0, PbTrackerTheme.PANEL_BORDER),
			BorderFactory.createEmptyBorder(8, 8, 8, 8)
		));
		outer.setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));

		JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(28, 28));
		icon.setHorizontalAlignment(SwingConstants.CENTER);
		BossIcons.get(spriteManager, row.iconKey, icon::setIcon);
		outer.add(icon, BorderLayout.WEST);

		JPanel textBlock = new JPanel();
		textBlock.setLayout(new BoxLayout(textBlock, BoxLayout.Y_AXIS));
		textBlock.setBackground(PbTrackerTheme.PANEL);
		// Bold at the normal (not "small") size - readability won out over
		// avoiding wraps, so a long name like "Theatre Of Blood" may now
		// take 2 lines rather than fitting on 1.
		JTextArea name = wrappedLabel(PbTrackerPlugin.wrapFriendly(row.primaryName), PbTrackerTheme.TEXT, true);
		textBlock.add(name);
		if (row.subtitle != null)
		{
			JTextArea subtitle = wrappedLabel(PbTrackerPlugin.wrapFriendly(row.subtitle), PbTrackerTheme.TEXT_DIM, false);
			textBlock.add(subtitle);
		}
		outer.add(textBlock, BorderLayout.CENTER);

		JPanel statsBlock = new JPanel();
		statsBlock.setLayout(new BoxLayout(statsBlock, BoxLayout.Y_AXIS));
		statsBlock.setBackground(PbTrackerTheme.PANEL);
		if (row.hasData)
		{
			JLabel time = new JLabel(PbTrackerPlugin.formatTime(row.timeSeconds));
			time.setForeground(PbTrackerTheme.GOLD_LIGHT);
			time.setFont(FontManager.getRunescapeBoldFont());
			time.setAlignmentX(java.awt.Component.RIGHT_ALIGNMENT);
			JLabel rank = new JLabel("#" + row.rank);
			rank.setForeground(PbTrackerTheme.TEXT_DIM);
			rank.setFont(FontManager.getRunescapeFont());
			rank.setAlignmentX(java.awt.Component.RIGHT_ALIGNMENT);
			statsBlock.add(time);
			statsBlock.add(rank);
		}
		else
		{
			// Plain ASCII "-" rather than an en dash - RuneLite's bitmap OSRS
			// font doesn't have a glyph for "–" and silently falls back to a
			// "tofu" box character instead (same issue as the old chevron).
			JLabel dash = new JLabel("-");
			dash.setForeground(PbTrackerTheme.TEXT_DIM);
			dash.setFont(FontManager.getRunescapeBoldFont());
			statsBlock.add(dash);
		}
		if (expandable)
		{
			// A visible arrow, not just an unmarked clickable row - a hidden
			// affordance here was the exact "where are my other team sizes?"
			// problem from before. Stacked below the rank rather than beside
			// it, so an expandable row costs no extra horizontal width and
			// doesn't force the name text to wrap any harder than a plain row.
			JLabel chevron = new JLabel(expanded ? "v" : ">");
			chevron.setForeground(PbTrackerTheme.GOLD_LIGHT);
			chevron.setFont(FontManager.getRunescapeBoldFont());
			chevron.setAlignmentX(java.awt.Component.RIGHT_ALIGNMENT);
			statsBlock.add(chevron);
		}
		outer.add(statsBlock, BorderLayout.EAST);

		if (expandable)
		{
			rowsByExpandKey.put(expandKey, outer);
		}

		addHoverHighlight(outer, PbTrackerTheme.PANEL, outer, textBlock, statsBlock);
		PbTrackerPlugin.addRowClickListener(outer, () ->
		{
			if (expandable)
			{
				if (expandedHeadings.contains(expandKey))
				{
					expandedHeadings.remove(expandKey);
				}
				else
				{
					expandedHeadings.add(expandKey);
				}
				rerender();
				centerRowInView(expandKey);
			}
			else
			{
				activateBoss(row.clickKey, displayName, onBossClick);
			}
		});
		addFullWidthRow(outer);

		if (expanded)
		{
			for (BossGroups.PlayerRaidVariant variant : row.variants)
			{
				if (isHiddenByConfig(variant.kind))
				{
					continue;
				}
				addVariantSubRow(variant, displayName, onBossClick);
			}
		}
	}

	/** Lets "Show Overall/Room times" settings hide the corresponding team-size sub-rows to declutter the breakdown. */
	private boolean isHiddenByConfig(BossGroups.VariantKind kind)
	{
		if (kind == BossGroups.VariantKind.OVERALL && !config.showOverallVariants())
		{
			return true;
		}
		return kind == BossGroups.VariantKind.ROOM && !config.showRoomVariants();
	}

	/** An indented, smaller row for one team-size/mode variant beneath its expanded raid+mode heading. */
	private void addVariantSubRow(BossGroups.PlayerRaidVariant variant, String displayName, BiConsumer<String, String> onBossClick)
	{
		JPanel row = new JPanel(new BorderLayout());
		row.setBackground(PbTrackerTheme.ROW_BG);
		row.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 1, 0, PbTrackerTheme.PANEL_BORDER),
			BorderFactory.createEmptyBorder(6, 20, 6, 8)
		));
		row.setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));

		JTextArea line = wrappedLabel(variant.label + "   " + PbTrackerPlugin.formatTime(variant.timeSeconds) + "   #" + variant.rank, PbTrackerTheme.TEXT, false);
		row.add(line, BorderLayout.CENTER);
		addHoverHighlight(row, PbTrackerTheme.ROW_BG, row);
		PbTrackerPlugin.addRowClickListener(row, () -> activateBoss(variant.key, displayName, onBossClick));
		addFullWidthRow(row);
	}

	/**
	 * A plain JLabel never wraps and just keeps growing wider, which is what
	 * caused the sidebar's horizontal scrollbar on long headings. A
	 * non-editable, unstyled JTextArea wraps at whatever width its
	 * container actually gives it, like the rest of the panel.
	 */
	private JTextArea wrappedLabel(String text, java.awt.Color color, boolean bold)
	{
		JTextArea area = new JTextArea(text);
		area.setEditable(false);
		area.setFocusable(false);
		area.setLineWrap(true);
		area.setWrapStyleWord(true);
		area.setOpaque(false);
		area.setForeground(color);
		area.setFont(bold ? FontManager.getRunescapeBoldFont() : FontManager.getRunescapeFont());
		area.setBorder(null);
		area.setAlignmentX(java.awt.Component.LEFT_ALIGNMENT);
		return area;
	}

	/**
	 * Recurses into every descendant (mirroring PbTrackerPlugin.addRowClickListener)
	 * so the highlight tracks the mouse regardless of which child label it's
	 * actually over, and paints every opaque panel in `targets` (the row's
	 * outer container plus any opaque sub-panels layered on top of it, which
	 * would otherwise hide a background change on the outer alone).
	 */
	private void addHoverHighlight(Component component, java.awt.Color normalColor, javax.swing.JComponent... targets)
	{
		component.addMouseListener(new java.awt.event.MouseAdapter()
		{
			@Override
			public void mouseEntered(java.awt.event.MouseEvent e)
			{
				for (javax.swing.JComponent target : targets)
				{
					target.setBackground(PbTrackerTheme.HIGHLIGHT_BG);
				}
			}

			@Override
			public void mouseExited(java.awt.event.MouseEvent e)
			{
				for (javax.swing.JComponent target : targets)
				{
					target.setBackground(normalColor);
				}
			}
		});
		if (component instanceof java.awt.Container)
		{
			for (Component child : ((java.awt.Container) component).getComponents())
			{
				addHoverHighlight(child, normalColor, targets);
			}
		}
	}

	/**
	 * GridBagLayout with horizontal fill avoids BoxLayout shrinking each card
	 * to its preferred text width, which left a large blank gutter beside
	 * shorter boss names in RuneLite's narrow sidebar.
	 */
	private void addFullWidthRow(Component component)
	{
		GridBagConstraints constraints = new GridBagConstraints();
		constraints.gridx = 0;
		constraints.gridy = rowsContainer.getComponentCount();
		constraints.weightx = 1.0;
		constraints.fill = GridBagConstraints.HORIZONTAL;
		constraints.anchor = GridBagConstraints.FIRST_LINE_START;
		rowsContainer.add(component, constraints);
	}

	private static void activateBoss(String bossKey, String displayName, BiConsumer<String, String> onBossClick)
	{
		log.debug("PB row activated: boss={}, player={}", bossKey, displayName);
		onBossClick.accept(bossKey, displayName);
	}

	/**
	 * Centers the just-toggled row in the enclosing scroll pane's viewport,
	 * instead of leaving Swing's default "keep the same pixel offset"
	 * behavior, which - since expanding pushes every row below it further
	 * down the now-taller list - reads as the whole panel randomly
	 * scrolling away from whatever you actually clicked. Deferred one tick
	 * so rerender()'s freshly rebuilt rows have already been laid out and
	 * their heights are known (same reasoning as BossesTab's leaderboard
	 * auto-scroll).
	 */
	private void centerRowInView(String expandKey)
	{
		javax.swing.SwingUtilities.invokeLater(() ->
		{
			Component row = rowsByExpandKey.get(expandKey);
			javax.swing.JViewport viewport = (javax.swing.JViewport)
				javax.swing.SwingUtilities.getAncestorOfClass(javax.swing.JViewport.class, this);
			if (row == null || viewport == null)
			{
				return;
			}

			java.awt.Point rowOrigin = javax.swing.SwingUtilities.convertPoint(row, 0, 0, viewport.getView());
			int viewportHeight = viewport.getExtentSize().height;
			int viewHeight = viewport.getView().getHeight();
			int targetY = rowOrigin.y - (viewportHeight - row.getHeight()) / 2;
			targetY = Math.max(0, Math.min(targetY, Math.max(0, viewHeight - viewportHeight)));
			viewport.setViewPosition(new java.awt.Point(0, targetY));
		});
	}
}

package com.pbtracker;

import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

import javax.swing.BorderFactory;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTabbedPane;
import java.awt.BorderLayout;
import java.awt.Component;
import java.util.function.Supplier;

/**
 * Root side panel: three tabs (My PBs / Player Search / Bosses), matching
 * the website's own three top-level views (player lookup, boss leaderboard)
 * plus a "my own stats" shortcut the site doesn't need (it's not tied to a
 * logged-in account the way the plugin is).
 * <p>
 * Clicking a boss on a PB row jumps to the Bosses tab with that boss's
 * leaderboard shown, highlighted on the clicked player - mirrors the
 * website's rank-click-through behaviour. Clicking a player on a
 * leaderboard row jumps to the Search tab and looks them up.
 * <p>
 * A "Back" bar appears above the tabs whenever one of those jumps fires,
 * remembering whichever tab you were on before it - previously the only
 * way back to (say) the boss list after following a PB row into the
 * Bosses tab was to click yet another boss, there was no way back to
 * just browsing.
 */
class PbTrackerSidePanel extends PluginPanel
{
	private final JTabbedPane tabs = new JTabbedPane();
	private final MyPbsTab myPbsTab;
	private final PlayerSearchTab searchTab;
	private final BossesTab bossesTab;

	private final JPanel backBar = new JPanel(new BorderLayout());
	private Component previousTab;

	PbTrackerSidePanel(SyncClient syncClient, SpriteManager spriteManager, PbTrackerConfig config, LocalProfileLoadCoordinator localProfileLoadCoordinator, Supplier<String> accountHashSupplier)
	{
		super(false);
		setBackground(PbTrackerTheme.BG);
		setLayout(new BorderLayout());

		bossesTab = new BossesTab(syncClient, spriteManager, this::jumpToSearch);
		myPbsTab = new MyPbsTab(syncClient, spriteManager, config, this::jumpToBoss, localProfileLoadCoordinator, accountHashSupplier);
		searchTab = new PlayerSearchTab(syncClient, spriteManager, config, this::jumpToBoss);

		tabs.setBackground(PbTrackerTheme.BG);
		tabs.setForeground(java.awt.Color.WHITE);
		tabs.addTab("My PBs", myPbsTab);
		tabs.addTab("Search", searchTab);
		tabs.addTab("Bosses", bossesTab);

		setUpBackBar();
		add(backBar, BorderLayout.NORTH);
		add(tabs, BorderLayout.CENTER);
	}

	private void setUpBackBar()
	{
		backBar.setBackground(PbTrackerTheme.BG);
		backBar.setBorder(BorderFactory.createEmptyBorder(6, 8, 0, 8));
		backBar.setVisible(false);

		JLabel backLabel = new JLabel("< Back");
		backLabel.setForeground(PbTrackerTheme.GOLD_LIGHT);
		backLabel.setFont(FontManager.getRunescapeBoldFont());
		backLabel.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(PbTrackerTheme.PANEL_BORDER),
			BorderFactory.createEmptyBorder(5, 10, 5, 10)
		));
		backLabel.setOpaque(true);
		backLabel.setBackground(PbTrackerTheme.PANEL);
		PbTrackerPlugin.addRowClickListener(backLabel, this::goBack);
		backBar.add(backLabel, BorderLayout.WEST);
	}

	private void showBackTo(Component current)
	{
		previousTab = current;
		backBar.setVisible(true);
		revalidate();
		repaint();
	}

	private void goBack()
	{
		if (previousTab != null)
		{
			tabs.setSelectedComponent(previousTab);
		}
		previousTab = null;
		backBar.setVisible(false);
		revalidate();
		repaint();
	}

	private void jumpToBoss(String bossKey, String highlightPlayerName)
	{
		showBackTo(tabs.getSelectedComponent());
		tabs.setSelectedComponent(bossesTab);
		bossesTab.showBossHighlighted(bossKey, highlightPlayerName);
	}

	private void jumpToSearch(String playerName)
	{
		showBackTo(tabs.getSelectedComponent());
		tabs.setSelectedComponent(searchTab);
		searchTab.searchFor(playerName);
	}

	/** Called on login/logout and whenever the panel is (re)activated. */
	void onLocalPlayerChanged(String displayName)
	{
		if (displayName == null)
		{
			myPbsTab.showLoggedOut();
		}
		else
		{
			myPbsTab.load(displayName);
		}
	}

	void setBosses(java.util.List<String> bosses)
	{
		bossesTab.setBosses(bosses);
		myPbsTab.setAllBosses(bosses);
		searchTab.setAllBosses(bosses);
	}

	/** Called by the right-click "Search PB" menu option. */
	void lookupPlayer(String name)
	{
		tabs.setSelectedComponent(searchTab);
		searchTab.searchFor(name);
	}

	void onSettingsChanged()
	{
		myPbsTab.onSettingsChanged();
		searchTab.onSettingsChanged();
	}
}

package com.pbtracker;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Ports frontend/src/lib/bossGroups.ts so the side panel can offer the same
 * "collapse raids into one row, then pick mode/team-size" experience as the
 * website, instead of a flat 200+ entry boss list. Kept behaviourally
 * identical on purpose - if the website's grouping logic changes, this
 * should change to match.
 */
final class BossGroups
{
	private BossGroups()
	{
	}

	enum Category
	{
		RAIDS("Raids"),
		SLAYER_MONSTERS("Slayer Monsters"),
		MINIGAMES("Minigames & Challenges"),
		BOSSES("Bosses"),
		OTHER("Other");

		final String label;

		Category(String label)
		{
			this.label = label;
		}
	}

	private static final List<String> RAID_PREFIXES = List.of("chambers of xeric", "theatre of blood", "tombs of amascut");
	private static final List<String> GROUPED_BOSS_PREFIXES = List.of(
		"chambers of xeric", "theatre of blood", "tombs of amascut", "the nightmare"
	);

	// The 6 Tzhaar-Ket-Rak challenges are separate boss keys entirely (no
	// " - "-delimited mode/size suffix like a raid variant), so they get
	// their own grouping path rather than going through parseRaidVariant's
	// raid-heading logic - collapsed into one "Tzhaar-Ket-Rak's Challenges"
	// heading instead of 6 flat rows cluttering the list.
	private static final String TZHAAR_CHALLENGE_PREFIX = "tzhaar-ket-rak's";
	private static final String TZHAAR_CHALLENGE_BASE = "tzhaar-ket-rak's challenges";
	// Built via titleCase() rather than hand-capitalized, so it matches what
	// getRaidModes() independently recomputes as titleCase(base) when the
	// user drills into this "raid base" from the picker.
	private static final String TZHAAR_CHALLENGES_HEADING = PbTrackerPlugin.titleCase(TZHAAR_CHALLENGE_BASE);
	private static final Map<String, Integer> TZHAAR_CHALLENGE_ORDER = Map.of(
		"first", 1, "second", 2, "third", 3, "fourth", 4, "fifth", 5, "sixth", 6
	);

	private static final List<String> SLAYER_MONSTERS = List.of(
		"kraken", "cerberus", "thermonuclear smoke devil", "alchemical hydra", "abyssal sire",
		"grotesque guardians", "araxxor", "shellbane gryphon", "skotizo", "kalphite queen"
	);

	private static final List<String> MINIGAMES = List.of(
		"tempoross", "wintertodt", "barbarian assault", "guardians of the rift", "gauntlet",
		"corrupted gauntlet", "inferno", "tzhaar fight cave", "fortis colosseum", "hallowed sepulchre",
		"shayzien basic agility course", "tzhaar-ket-rak's first challenge", "tzhaar-ket-rak's second challenge",
		"tzhaar-ket-rak's third challenge", "tzhaar-ket-rak's fourth challenge"
	);

	private static final List<String> KNOWN_BOSSES = List.of(
		"nex", "zulrah", "vorkath", "sarachnis", "vardorvis", "duke sucellus", "leviathan", "whisperer",
		"general graardor", "kree'arra", "commander zilyana", "k'ril tsutsaroth", "callisto", "artio",
		"venenatis", "spindel", "vet'ion", "calvar'ion", "chaos elemental", "chaos fanatic",
		"crazy archaeologist", "deranged archaeologist", "king black dragon", "giant mole", "zalcano",
		"obor", "bryophyta", "dagannoth rex", "dagannoth prime", "dagannoth supreme", "corporeal beast",
		"nightmare", "phosani's nightmare", "scorpia", "tztok-jad", "amoxliatl", "brutus",
		"fragment of seren", "galvek", "hespori", "maggot king", "mimic", "phantom muspah",
		"royal titans", "scurrius", "shellbane gryphon", "hueycoatl", "yama"
	);

	// Entry < Normal < Hard/Challenge Mode/Expert - see bossGroups.ts's
	// MODE_PRIORITY for why they share a rank.
	private static final Map<String, Integer> MODE_PRIORITY = Map.of(
		"entry", 1,
		"", 2,
		"hard", 3,
		"challenge mode", 3,
		"expert", 3
	);

	static String normalize(String key)
	{
		String lower = key.trim().toLowerCase();
		return lower.startsWith("the ") ? lower.substring(4) : lower;
	}

	private static boolean matchesCurated(String key, List<String> curated)
	{
		String n = normalize(key);
		for (String name : curated)
		{
			if (n.equals(name) || n.startsWith(name + " (") || n.startsWith(name + " -"))
			{
				return true;
			}
		}
		return false;
	}

	private static boolean isRaid(String key)
	{
		String lower = key.trim().toLowerCase();
		for (String p : RAID_PREFIXES)
		{
			if (lower.equals(p) || lower.startsWith(p + " -") || lower.startsWith(p + " "))
			{
				return true;
			}
		}
		return false;
	}

	static boolean isGroupedVariant(String key)
	{
		String lower = key.trim().toLowerCase();
		if (lower.startsWith(TZHAAR_CHALLENGE_PREFIX))
		{
			return true;
		}
		for (String p : GROUPED_BOSS_PREFIXES)
		{
			if (lower.equals(p) || lower.startsWith(p + " -"))
			{
				return true;
			}
		}
		return false;
	}

	static Category categorize(String bossKey)
	{
		if (isRaid(bossKey))
		{
			return Category.RAIDS;
		}
		if (matchesCurated(bossKey, SLAYER_MONSTERS))
		{
			return Category.SLAYER_MONSTERS;
		}
		if (matchesCurated(bossKey, MINIGAMES))
		{
			return Category.MINIGAMES;
		}
		if (matchesCurated(bossKey, KNOWN_BOSSES))
		{
			return Category.BOSSES;
		}
		if (normalize(bossKey).startsWith("nightmare "))
		{
			return Category.BOSSES;
		}
		return Category.OTHER;
	}

	static final class RaidVariant
	{
		final String key;
		final String base;
		final String mode;
		final String heading;
		final String subLabel;

		RaidVariant(String key, String base, String mode, String heading, String subLabel)
		{
			this.key = key;
			this.base = base;
			this.mode = mode;
			this.heading = heading;
			this.subLabel = subLabel;
		}
	}

	private static RaidVariant parseRaidVariant(String bossKey)
	{
		String lower = bossKey.trim().toLowerCase();
		if (lower.startsWith(TZHAAR_CHALLENGE_PREFIX))
		{
			String subLabel = PbTrackerPlugin.titleCase(lower.substring(TZHAAR_CHALLENGE_PREFIX.length()).trim());
			return new RaidVariant(bossKey, TZHAAR_CHALLENGE_BASE, "", TZHAAR_CHALLENGES_HEADING, subLabel);
		}

		String[] segments = bossKey.trim().toLowerCase().split(" - ");
		for (int i = 0; i < segments.length; i++)
		{
			segments[i] = segments[i].trim();
		}
		String base = segments[0];
		String mode = segments.length > 2
			? String.join(" - ", java.util.Arrays.copyOfRange(segments, 1, segments.length - 1))
			: "";
		String heading = mode.isEmpty() ? PbTrackerPlugin.titleCase(base) : PbTrackerPlugin.titleCase(base) + " - " + PbTrackerPlugin.titleCase(mode);
		boolean isBareOverall = segments.length == 1;
		String subLabel = isBareOverall ? "Overall" : PbTrackerPlugin.titleCase(segments[segments.length - 1]);
		return new RaidVariant(bossKey, base, mode, heading, subLabel);
	}

	private static final Pattern DIGIT_PATTERN = Pattern.compile("(\\d+)");

	private static int teamSizeRank(String subLabel)
	{
		String lower = subLabel.toLowerCase();
		if (lower.contains("solo"))
		{
			return 1;
		}
		for (Map.Entry<String, Integer> ordinal : TZHAAR_CHALLENGE_ORDER.entrySet())
		{
			if (lower.startsWith(ordinal.getKey()))
			{
				return ordinal.getValue();
			}
		}
		Matcher m = DIGIT_PATTERN.matcher(lower);
		return m.find() ? Integer.parseInt(m.group(1)) : 999;
	}

	private static int variantRank(String subLabel)
	{
		return subLabel.toLowerCase().startsWith("fastest overall") ? 0 : 1;
	}

	private static final Map<Integer, String> SIZE_NICKNAMES = Map.of(1, "Solo", 2, "Duo", 3, "Trio");
	private static final Pattern SIZE_PATTERN = Pattern.compile("(\\d+)(\\+)?\\s*players?");
	private static final Pattern SOLO_PATTERN = Pattern.compile("\\bsolo\\b");

	/** Null means "no team size in this label" (e.g. legacy "(Former)" entries) - caller falls back to the full label. */
	static String sizeLabel(String label)
	{
		String lower = label.toLowerCase();
		if (SOLO_PATTERN.matcher(lower).find())
		{
			return "Solo";
		}
		Matcher m = SIZE_PATTERN.matcher(lower);
		if (!m.find())
		{
			return null;
		}
		int n = Integer.parseInt(m.group(1));
		if (m.group(2) != null)
		{
			return n + "+";
		}
		return SIZE_NICKNAMES.getOrDefault(n, n + "-Man");
	}

	enum VariantKind
	{
		OVERALL, ROOM, OTHER, LEGACY
	}

	private static VariantKind variantKind(String label)
	{
		String lower = label.toLowerCase();
		if (lower.contains("(former)"))
		{
			return VariantKind.LEGACY;
		}
		if (lower.equals("overall") || lower.startsWith("fastest overall"))
		{
			return VariantKind.OVERALL;
		}
		if (lower.startsWith("fastest room"))
		{
			return VariantKind.ROOM;
		}
		return VariantKind.OTHER;
	}

	static final class RaidGroup
	{
		final String heading;
		final String base;
		final String mode;
		final List<KeyLabel> variants;

		RaidGroup(String heading, String base, String mode, List<KeyLabel> variants)
		{
			this.heading = heading;
			this.base = base;
			this.mode = mode;
			this.variants = variants;
		}
	}

	static final class KeyLabel
	{
		final String key;
		final String label;

		KeyLabel(String key, String label)
		{
			this.key = key;
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	/** One RaidGroup per raid+mode heading, found across every bare boss key in `bosses`. */
	static List<RaidGroup> groupedRaidGroups(List<String> bosses)
	{
		List<String> groupedKeys = new ArrayList<>();
		for (String b : bosses)
		{
			if (isGroupedVariant(b))
			{
				groupedKeys.add(b);
			}
		}

		Map<String, List<RaidVariant>> byHeading = new LinkedHashMap<>();
		for (String key : groupedKeys)
		{
			RaidVariant variant = parseRaidVariant(key);
			byHeading.computeIfAbsent(variant.heading, h -> new ArrayList<>()).add(variant);
		}

		List<RaidGroup> groups = new ArrayList<>();
		for (List<RaidVariant> variants : byHeading.values())
		{
			List<RaidVariant> sorted = new ArrayList<>(variants);
			sorted.sort(Comparator.<RaidVariant>comparingInt(v -> teamSizeRank(v.subLabel))
				.thenComparingInt(v -> variantRank(v.subLabel)));

			// Compact "Fastest Overall (1 Player Hard Mode)" down to just
			// "1 Player" (sizeLabel()) like the player-specific grouping
			// already does - otherwise every team-size button repeats the
			// same wall of near-identical verbose text and doesn't read as
			// a size picker at all. Two variants can still share a team
			// size (an "Overall" time and a "Room" time), so disambiguate
			// those with an "Overall"/"Room" suffix only when they collide.
			List<String> niceLabels = new ArrayList<>();
			for (RaidVariant v : sorted)
			{
				String nice = sizeLabel(v.subLabel);
				niceLabels.add(nice != null ? nice : v.subLabel);
			}
			Map<String, Integer> labelCounts = new LinkedHashMap<>();
			for (String label : niceLabels)
			{
				labelCounts.merge(label, 1, Integer::sum);
			}
			List<KeyLabel> variantList = new ArrayList<>();
			for (int i = 0; i < sorted.size(); i++)
			{
				String nice = niceLabels.get(i);
				String finalLabel = labelCounts.get(nice) > 1 ? nice + " - " + kindName(variantKind(sorted.get(i).subLabel)) : nice;
				variantList.add(new KeyLabel(sorted.get(i).key, finalLabel));
			}
			groups.add(new RaidGroup(variants.get(0).heading, variants.get(0).base, variants.get(0).mode, variantList));
		}

		groups.sort(Comparator.<RaidGroup, String>comparing(g -> g.base)
			.thenComparingInt(g -> MODE_PRIORITY.getOrDefault(g.mode, g.mode.isEmpty() ? 0 : 50)));
		return groups;
	}

	static final class RaidBase
	{
		final String base;
		final String label;

		RaidBase(String base, String label)
		{
			this.base = base;
			this.label = label;
		}
	}

	/** Every non-raid boss key in `bosses`, deduplicated - for enumerating "every boss that could show up" regardless of whether this player has PBs for it. */
	static List<String> getFlatBossKeys(List<String> bosses)
	{
		List<String> flat = new ArrayList<>();
		java.util.Set<String> seen = new java.util.HashSet<>();
		for (String b : bosses)
		{
			if (!isGroupedVariant(b) && seen.add(b.trim().toLowerCase()))
			{
				flat.add(b);
			}
		}
		return flat;
	}

	/** One row per raid base (mode-independent) - for the top-level "pick a raid" list. */
	static List<RaidBase> getRaidBases(List<String> bosses)
	{
		Map<String, RaidBase> seen = new LinkedHashMap<>();
		for (RaidGroup group : groupedRaidGroups(bosses))
		{
			String label = group.heading.contains(" - ") ? group.heading.substring(0, group.heading.indexOf(" - ")) : group.heading;
			String base = label.toLowerCase();
			seen.putIfAbsent(base, new RaidBase(base, label));
		}
		List<RaidBase> result = new ArrayList<>(seen.values());
		result.sort(Comparator.comparing(b -> b.label));
		return result;
	}

	static final class RaidMode
	{
		final String modeLabel;
		final List<KeyLabel> variants;

		RaidMode(String modeLabel, List<KeyLabel> variants)
		{
			this.modeLabel = modeLabel;
			this.variants = variants;
		}
	}

	/** Every mode (Normal/Entry/Hard/Challenge Mode/Expert) for a single raid base. */
	static List<RaidMode> getRaidModes(List<String> bosses, String base)
	{
		String baseLabel = PbTrackerPlugin.titleCase(base);
		List<RaidMode> modes = new ArrayList<>();
		for (RaidGroup group : groupedRaidGroups(bosses))
		{
			if (group.heading.equals(baseLabel) || group.heading.startsWith(baseLabel + " - "))
			{
				String modeLabel = group.heading.equals(baseLabel) ? "Normal" : group.heading.substring(baseLabel.length() + 3);
				modes.add(new RaidMode(modeLabel, group.variants));
			}
		}
		return modes;
	}

	// ---- Player-PB-specific grouping (for "My PBs" / player search results) ----

	static final class PlayerPb
	{
		final String boss;
		final double timeSeconds;
		final int rank;
		final String updatedAt;

		PlayerPb(String boss, double timeSeconds, int rank, String updatedAt)
		{
			this.boss = boss;
			this.timeSeconds = timeSeconds;
			this.rank = rank;
			this.updatedAt = updatedAt;
		}
	}

	static final class PlayerRaidVariant
	{
		final String key;
		final String label;
		final VariantKind kind;
		final double timeSeconds;
		final int rank;
		final String updatedAt;

		PlayerRaidVariant(String key, String label, VariantKind kind, double timeSeconds, int rank, String updatedAt)
		{
			this.key = key;
			this.label = label;
			this.kind = kind;
			this.timeSeconds = timeSeconds;
			this.rank = rank;
			this.updatedAt = updatedAt;
		}

		PlayerRaidVariant withLabel(String newLabel)
		{
			return new PlayerRaidVariant(key, newLabel, kind, timeSeconds, rank, updatedAt);
		}
	}

	static final class PlayerRaidGroup
	{
		final String heading;
		final PlayerRaidVariant summary;
		final List<PlayerRaidVariant> variants;

		PlayerRaidGroup(String heading, PlayerRaidVariant summary, List<PlayerRaidVariant> variants)
		{
			this.heading = heading;
			this.summary = summary;
			this.variants = variants;
		}
	}

	static final class GroupedPlayerPbs
	{
		final List<PlayerRaidGroup> groups;
		final List<PlayerPb> flat;

		GroupedPlayerPbs(List<PlayerRaidGroup> groups, List<PlayerPb> flat)
		{
			this.groups = groups;
			this.flat = flat;
		}
	}

	private static final VariantKind[] KIND_PREFERENCE = { VariantKind.OVERALL, VariantKind.ROOM, VariantKind.OTHER, VariantKind.LEGACY };

	private static PlayerRaidVariant pickSummary(List<PlayerRaidVariant> variants)
	{
		for (VariantKind kind : KIND_PREFERENCE)
		{
			PlayerRaidVariant fastest = null;
			for (PlayerRaidVariant v : variants)
			{
				if (v.kind == kind && (fastest == null || v.timeSeconds < fastest.timeSeconds))
				{
					fastest = v;
				}
			}
			if (fastest != null)
			{
				return fastest;
			}
		}
		return variants.get(0);
	}

	static PlayerRaidVariant pickBestRanked(List<PlayerRaidVariant> variants)
	{
		return variants.stream()
			.min(Comparator.comparingInt((PlayerRaidVariant v) -> v.rank)
				.thenComparingDouble(v -> v.timeSeconds))
			.orElseThrow(() -> new IllegalArgumentException("variants must not be empty"));
	}

	/** Groups a player's own synced PBs into one row per raid+mode heading, for display. */
	static GroupedPlayerPbs groupPlayerRaidPbs(List<PlayerPb> pbs)
	{
		List<PlayerPb> flat = new ArrayList<>();
		Map<String, List<Object[]>> byHeading = new LinkedHashMap<>(); // [PlayerRaidVariant, subLabel]

		for (PlayerPb pb : pbs)
		{
			if (!isGroupedVariant(pb.boss))
			{
				flat.add(pb);
				continue;
			}
			RaidVariant parsed = parseRaidVariant(pb.boss);
			String niceLabel = sizeLabel(parsed.subLabel);
			PlayerRaidVariant entry = new PlayerRaidVariant(
				pb.boss, niceLabel != null ? niceLabel : parsed.subLabel, variantKind(parsed.subLabel),
				pb.timeSeconds, pb.rank, pb.updatedAt
			);
			byHeading.computeIfAbsent(parsed.heading, h -> new ArrayList<>()).add(new Object[] { entry, parsed.subLabel });
		}

		List<PlayerRaidGroup> groups = new ArrayList<>();
		for (Map.Entry<String, List<Object[]>> entry : byHeading.entrySet())
		{
			List<Object[]> raw = entry.getValue();
			raw.sort(Comparator.<Object[]>comparingInt(o -> teamSizeRank((String) o[1]))
				.thenComparingInt(o -> variantRank((String) o[1])));

			List<PlayerRaidVariant> sorted = new ArrayList<>();
			for (Object[] o : raw)
			{
				sorted.add((PlayerRaidVariant) o[0]);
			}

			PlayerRaidVariant summary = pickSummary(sorted);

			Map<String, Integer> labelCounts = new LinkedHashMap<>();
			for (PlayerRaidVariant v : sorted)
			{
				labelCounts.merge(v.label, 1, Integer::sum);
			}
			List<PlayerRaidVariant> labeled = new ArrayList<>();
			for (PlayerRaidVariant v : sorted)
			{
				labeled.add(labelCounts.get(v.label) > 1 ? v.withLabel(v.label + " - " + kindName(v.kind)) : v);
			}

			groups.add(new PlayerRaidGroup(entry.getKey(), summary, labeled));
		}

		groups.sort(Comparator.comparing(g -> g.heading));
		return new GroupedPlayerPbs(groups, flat);
	}

	private static String kindName(VariantKind kind)
	{
		switch (kind)
		{
			case OVERALL:
				return "Overall";
			case ROOM:
				return "Room";
			case LEGACY:
				return "Legacy";
			default:
				return "Other";
		}
	}
}

package com.pbtracker;

import net.runelite.client.game.SpriteManager;

import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextField;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingUtilities;
import java.awt.BorderLayout;
import java.awt.event.ActionListener;
import java.util.function.BiConsumer;

/**
 * "Player Search" tab - a name box + the same PbListPanel rendering used by
 * MyPbsTab, so results look identical whether you're looking at your own
 * data or someone else's.
 */
class PlayerSearchTab extends JPanel
{
	private final SyncClient syncClient;
	private final BiConsumer<String, String> onBossClickHandler;
	private final PbListPanel listPanel;
	private final JTextField searchField = new JTextField();
	private final JScrollPane scrollPane;
	private long requestGeneration;

	PlayerSearchTab(SyncClient syncClient, SpriteManager spriteManager, PbTrackerConfig config, BiConsumer<String, String> onBossClick)
	{
		this.syncClient = syncClient;
		this.onBossClickHandler = onBossClick;
		this.listPanel = new PbListPanel(spriteManager, config);
		setLayout(new BorderLayout());
		setBackground(PbTrackerTheme.BG);

		JPanel searchBar = new JPanel(new BorderLayout(6, 0));
		searchBar.setBackground(PbTrackerTheme.BG);
		searchBar.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

		searchField.setBackground(PbTrackerTheme.PANEL);
		searchField.setForeground(PbTrackerTheme.TEXT);
		ActionListener search = e -> doSearch();
		searchField.addActionListener(search);

		JButton searchButton = new JButton("Search");
		searchButton.addActionListener(search);

		searchBar.add(searchField, BorderLayout.CENTER);
		searchBar.add(searchButton, BorderLayout.EAST);

		add(searchBar, BorderLayout.NORTH);

		scrollPane = new JScrollPane(listPanel);
		scrollPane.setBorder(null);
		scrollPane.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scrollPane.getVerticalScrollBar().setUnitIncrement(16);
		add(scrollPane, BorderLayout.CENTER);

		listPanel.showMessage("Search a player to see their synced PBs.");
	}

	/** Every boss key this plugin knows about system-wide - forwarded to the list panel so untracked bosses can show a dash instead of being omitted. */
	void setAllBosses(java.util.List<String> bosses)
	{
		listPanel.setAllBosses(bosses);
	}

	private void doSearch()
	{
		String name = searchField.getText().trim();
		if (name.isEmpty())
		{
			return;
		}
		searchFor(name);
	}

	/** Also used by the right-click "Search PB" menu option, which switches to this tab and searches directly. */
	void searchFor(String name)
	{
		searchField.setText(name);
		listPanel.showMessage("Loading...");
		long request = ++requestGeneration;
		new Thread(() ->
		{
			SyncClient.PlayerLookupResult result = syncClient.lookupPlayer(name);
			SwingUtilities.invokeLater(() ->
			{
				if (request != requestGeneration)
				{
					return;
				}
				switch (result.kind)
				{
					case FOUND:
						listPanel.showPlayer(result.player, onBossClickHandler);
						scrollToTop();
						break;
					case NOT_FOUND:
						listPanel.showMessage("No synced PB data found for \"" + name + "\" yet.");
						break;
					case AMBIGUOUS:
						listPanel.showMessage("Multiple synced accounts share this name - check the website directly.");
						break;
					case ERROR:
					default:
						listPanel.showMessage("Lookup failed - try again later.");
						break;
				}
			});
		}, "pbtracker-search-lookup").start();
	}

	private void scrollToTop()
	{
		SwingUtilities.invokeLater(() -> scrollPane.getViewport().setViewPosition(new java.awt.Point(0, 0)));
	}

	void onSettingsChanged()
	{
		listPanel.onSettingsChanged();
	}
}

package com.pbtracker;

import java.util.Locale;
import java.util.Objects;

/**
 * Decides whether the "My PBs" sidebar should issue a fresh
 * GET /api/players/:name lookup, independent of the syncOnLogin-gated
 * automatic sync scheduler. RuneLite can publish LOGGED_IN more than once
 * per account session (startup, world hops, reconnects), and without this
 * gate every one of those re-triggers a lookup thread.
 * <p>
 * Deliberately has no RuneLite/Swing dependency so it can be unit-tested
 * without timing real UI threads - mirrors PbTrackerPlugin.LoginSyncSession.
 */
class LocalProfileLoadCoordinator
{
	static final long ERROR_BACKOFF_MILLIS = 30_000;

	enum Decision
	{
		LOAD,
		SKIP_ALREADY_LOADED,
		SKIP_IN_FLIGHT,
		SKIP_BACKOFF
	}

	private String accountHash;
	private String normalizedDisplayName;
	private boolean inFlight;
	private boolean loaded;
	private boolean pendingRefresh;
	private boolean profileMayChangeAfterSuccessfulSync;
	private boolean successfulSyncObservedDuringLoad;
	private long lastFailureAtMillis = -1;

	/** Called for every LOGGED_IN state the plugin observes. */
	synchronized Decision onLoginState(String currentAccountHash, String displayName, long nowMillis)
	{
		String normalized = normalize(displayName);
		boolean sameSession = isSameSession(currentAccountHash, normalized);

		if (!sameSession)
		{
			startNewSession(currentAccountHash, normalized);
		}

		if (inFlight)
		{
			return Decision.SKIP_IN_FLIGHT;
		}
		if (loaded)
		{
			return Decision.SKIP_ALREADY_LOADED;
		}
		if (lastFailureAtMillis >= 0 && nowMillis - lastFailureAtMillis < ERROR_BACKOFF_MILLIS)
		{
			return Decision.SKIP_BACKOFF;
		}

		inFlight = true;
		return Decision.LOAD;
	}

	/**
	 * Called by the explicit "Refresh My PBs" action. Bypasses the
	 * loaded-session cache and the error backoff, but still coalesces a
	 * concurrent in-flight request for the same session.
	 */
	synchronized Decision onManualRefresh(String currentAccountHash, String displayName)
	{
		String normalized = normalize(displayName);
		boolean sameSession = isSameSession(currentAccountHash, normalized);
		if (sameSession && inFlight)
		{
			return Decision.SKIP_IN_FLIGHT;
		}

		if (!sameSession)
		{
			startNewSession(currentAccountHash, normalized);
		}

		inFlight = true;
		return Decision.LOAD;
	}

	/**
	 * @return true if a changed-sync refresh was owed (pendingRefresh had
	 * been set) and was just consumed here rather than being fully
	 * satisfied - the caller should immediately start another load instead
	 * of treating the session as up to date.
	 */
	synchronized boolean markLoaded()
	{
		return markLoaded(false);
	}

	/**
	 * Records a successful lookup.
	 *
	 * @param profileMayChangeAfterSuccessfulSync true when this response
	 * indicates that a later successful sync could make the lookup resolve
	 * differently (for example NOT_FOUND or a stale returned display name)
	 * @return true when the caller must immediately retry the lookup
	 */
	synchronized boolean markLoaded(boolean profileMayChangeAfterSuccessfulSync)
	{
		lastFailureAtMillis = -1;
		boolean retry = pendingRefresh
			|| successfulSyncObservedDuringLoad && profileMayChangeAfterSuccessfulSync;
		pendingRefresh = false;
		successfulSyncObservedDuringLoad = false;
		if (retry)
		{
			loaded = false;
			this.profileMayChangeAfterSuccessfulSync = false;
			// inFlight stays true - the caller is required to immediately
			// retry, so from the coordinator's point of view a fetch is
			// still ongoing until that retry itself completes.
			return true;
		}
		inFlight = false;
		loaded = true;
		this.profileMayChangeAfterSuccessfulSync = profileMayChangeAfterSuccessfulSync;
		return false;
	}

	/**
	 * @return true when a successful sync arrived during this failed lookup
	 * and the caller must immediately make the one deferred retry
	 */
	synchronized boolean markError(long nowMillis)
	{
		boolean retry = pendingRefresh || successfulSyncObservedDuringLoad;
		pendingRefresh = false;
		successfulSyncObservedDuringLoad = false;
		if (retry)
		{
			loaded = false;
			profileMayChangeAfterSuccessfulSync = false;
			lastFailureAtMillis = -1;
			// Keep inFlight held across the immediate retry hand-off.
			return true;
		}
		inFlight = false;
		lastFailureAtMillis = nowMillis;
		return false;
	}

	/**
	 * Applies a non-replayed successful sync to the current lookup state.
	 * Unchanged syncs retain a valid loaded profile, but can refresh a prior
	 * NOT_FOUND/stale-name result or retry one failed/in-flight lookup.
	 *
	 * @return true when the caller should ask the normal load path to refresh
	 */
	synchronized boolean requestRefreshAfterSuccessfulSync(boolean responseIndicatesProfileChange)
	{
		if (inFlight)
		{
			if (responseIndicatesProfileChange)
			{
				pendingRefresh = true;
			}
			else
			{
				successfulSyncObservedDuringLoad = true;
			}
			return responseIndicatesProfileChange;
		}

		if (!responseIndicatesProfileChange
			&& !profileMayChangeAfterSuccessfulSync
			&& lastFailureAtMillis < 0)
		{
			return false;
		}

		loaded = false;
		profileMayChangeAfterSuccessfulSync = false;
		lastFailureAtMillis = -1;
		return true;
	}

	/** Compatibility helper for the coordinator's changed-data unit tests. */
	synchronized void markStaleAfterChangedSync()
	{
		requestRefreshAfterSuccessfulSync(true);
	}

	/** Logout / login-screen state: cancel any pending retry and clear the session entirely. */
	synchronized void reset()
	{
		accountHash = null;
		normalizedDisplayName = null;
		inFlight = false;
		loaded = false;
		pendingRefresh = false;
		profileMayChangeAfterSuccessfulSync = false;
		successfulSyncObservedDuringLoad = false;
		lastFailureAtMillis = -1;
	}

	private void startNewSession(String currentAccountHash, String normalizedDisplayName)
	{
		this.accountHash = currentAccountHash;
		this.normalizedDisplayName = normalizedDisplayName;
		this.inFlight = false;
		this.loaded = false;
		this.pendingRefresh = false;
		this.profileMayChangeAfterSuccessfulSync = false;
		this.successfulSyncObservedDuringLoad = false;
		this.lastFailureAtMillis = -1;
	}

	private boolean isSameSession(String currentAccountHash, String normalizedDisplayName)
	{
		return Objects.equals(currentAccountHash, accountHash)
			&& Objects.equals(normalizedDisplayName, this.normalizedDisplayName);
	}

	private static String normalize(String displayName)
	{
		return displayName == null ? "" : displayName.trim().toLowerCase(Locale.ROOT);
	}
}

